# Cases of those who kept the law and the blessing recorded for it. kind="blessing", verdict="blessed".
# Fields keep the case schema: `charge` is the commendation, `offense` the obedience, `judgment` the blessing.
def R(book, ch, vv=None):
    return {"book": book, "chapter": ch, **({"verses": vv} if vv else {})}
def B(**kw):
    kw.setdefault("kind", "blessing"); kw.setdefault("verdict", "blessed"); return kw

CASES = [
 # ---------------- Primeval ----------------
 B(slug="abel", name="Abel", era="Primeval", charge="Bringing the firstlings of his flock and the fat thereof",
  summary="The first offering scripture records as accepted, and the first man it calls righteous. Abel brought the firstlings and the fat, and the Lord had respect unto him. His brother's envy killed him, and his blood still speaks.",
  offense="Abel, he also brought of the firstlings of his flock and of the fat thereof. By faith Abel offered unto God a more excellent sacrifice than Cain: the first and the best, not the leftover, and brought in faith. The law of the firstlings and the fat was written later; Abel kept it before it was written.",
  judgment="The Lord had respect unto Abel and to his offering. By it he obtained witness that he was righteous, God testifying of his gifts: and by it he being dead yet speaketh. Christ names him righteous Abel, the first of the prophets whose blood was shed. His blessing is a standing before God that outlasted his life.",
  refs=[R("Genesis",4,"2-5"),R("Hebrews",11,"4"),R("Matthew",23,"35"),R("Exodus",13,"12"),R("Leviticus",3,"16"),R("1 John",3,"12")],
  laws=["20E","2J","2B"], topics=["firstborn","giving","righteousness"], themes=["faith","sacrifice","martyrdom","obedience"]),

 B(slug="enoch", name="Enoch", era="Primeval", charge="Walking with God three hundred years",
  summary="Seventh from Adam, he walked with God after Methuselah was born, and was not, for God took him. Before his translation he had this testimony, that he pleased God. He is the first man scripture says did not see death.",
  offense="Enoch walked with God after he begat Methuselah three hundred years, and begat sons and daughters. Jude records that he prophesied of the Lord coming with ten thousands of his saints to execute judgment on the ungodly. Sirach: Enoch pleased the Lord, and was translated, being an example of repentance to all generations.",
  judgment="And Enoch walked with God: and he was not; for God took him. By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God.",
  refs=[R("Genesis",5,"21-24"),R("Hebrews",11,"5-6"),R("Jude",1,"14-15"),R("Sirach",44,"16"),R("Sirach",49,"14"),R("Wisdom of Solomon",4,"10-14")],
  laws=["2H","2B","2E"], topics=["obedience","believe","godly"], themes=["faith","obedience","deliverance"]),

 B(slug="noah", name="Noah", era="Primeval", charge="Doing according to all that God commanded him",
  summary="In a world where every imagination of man's heart was only evil continually, one man was just and perfect in his generations and walked with God. He was told to build an ark and did it exactly, and he and his house were the only ones saved through the flood.",
  offense="Noah was a just man and perfect in his generations, and Noah walked with God. Thus did Noah; according to all that God commanded him, so did he. By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house. Peter calls him a preacher of righteousness.",
  judgment="But Noah found grace in the eyes of the Lord. With thee will I establish my covenant; and thou shalt come into the ark, thou, and thy sons, and thy wife, and thy sons' wives with thee. After the flood God blessed Noah and his sons, gave them the earth, set the bow in the cloud, and swore that the waters would no more become a flood to destroy all flesh. Eight souls were saved by water, and the world began again from his house.",
  refs=[R("Genesis",6,"8-9"),R("Genesis",6,"13-22"),R("Genesis",7,"1"),R("Genesis",8,"20-22"),R("Genesis",9,"1-17"),R("Hebrews",11,"7"),R("2 Peter",2,"5"),R("Ezekiel",14,"14")],
  laws=["2H","2B","2C","2J"], topics=["obedience","believe","fear-god","doctrine-flood"], themes=["faith","obedience","covenant","deliverance"]),

 # ---------------- Patriarchal ----------------
 B(slug="abraham", name="Abraham", era="Patriarchal", charge="Obeying the Lord's voice; keeping his charge, his commandments, his statutes, and his laws",
  summary="Told to leave country, kindred and father's house for a land he would be shewed, he went. Told to offer his only son, he rose early in the morning. The Lord's own account of him, given to Isaac, is the law kept: Abraham obeyed my voice, and kept my charge, my commandments, my statutes, and my laws.",
  offense="By faith Abraham, when he was called to go out into a place which he should after receive for an inheritance, obeyed; and he went out, not knowing whither he went. He believed in the Lord, and he counted it to him for righteousness. He circumcised every male of his house the selfsame day he was commanded. He commanded his children and his household after him to keep the way of the Lord, to do justice and judgment. When tried, he offered up Isaac, accounting that God was able to raise him up.",
  judgment="I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing. By myself have I sworn, saith the Lord, for because thou hast done this thing, and hast not withheld thy son, thine only son: that in blessing I will bless thee, and in multiplying I will multiply thy seed as the stars of the heaven; and in thy seed shall all the nations of the earth be blessed; because thou hast obeyed my voice. He was called the friend of God, and the covenant with his seed stands.",
  refs=[R("Genesis",12,"1-4"),R("Genesis",15,"5-6"),R("Genesis",17,"23-27"),R("Genesis",18,"17-19"),R("Genesis",22,"1-3"),R("Genesis",22,"15-18"),R("Genesis",26,"3-5"),R("Hebrews",11,"8-10"),R("Hebrews",11,"17-19"),R("James",2,"21-23")],
  laws=["2H","2B","2F","6A","2E"], topics=["obedience","believe","keep-the-commandments","training-children","chosen"], themes=["faith","obedience","covenant","inheritance","family"]),

 B(slug="lot", name="Lot", era="Patriarchal", charge="A righteous man vexed with the filthy conversation of the wicked; sheltering the strangers at his door",
  summary="He chose the plain of Sodom and lived to regret it, but Peter calls him just Lot, vexed from day to day with the unlawful deeds of the city. He took the two strangers into his house and stood in his door against the men of the city. The angels took him by the hand and led him out before the fire fell.",
  offense="Lot sat in the gate of Sodom and rose up to meet the two angels, and pressed upon them greatly to turn in to his house, and made them a feast, and baked unleavened bread. When the men of the city compassed the house he went out and shut the door after him and said, I pray you, brethren, do not so wickedly. Peter: that righteous man dwelling among them, in seeing and hearing, vexed his righteous soul from day to day with their unlawful deeds.",
  judgment="The men said unto Lot, Hast thou here any besides? bring them out of this place: for we will destroy this place. While he lingered, the men laid hold upon his hand, and upon the hand of his wife, and upon the hand of his two daughters; the Lord being merciful unto him: and they brought him forth, and set him without the city. God remembered Abraham, and sent Lot out of the midst of the overthrow. The Lord knoweth how to deliver the godly out of temptations.",
  refs=[R("Genesis",19,"1-3"),R("Genesis",19,"6-8"),R("Genesis",19,"12-17"),R("Genesis",19,"29"),R("2 Peter",2,"6-9"),R("Hebrews",13,"2")],
  laws=["15A","12F","2C"], topics=["strangers","deliverance","sodomy"], themes=["hospitality","deliverance","mercy","faith"]),

 B(slug="isaac", name="Isaac", era="Patriarchal", charge="Dwelling in the land the Lord told him of, and not going down into Egypt in the famine",
  summary="A famine came, and the natural road was Egypt, where his father had gone. The Lord appeared and said, Go not down into Egypt; sojourn in this land, and I will be with thee. Isaac stayed in Gerar, sowed in a famine year, and reaped an hundredfold.",
  offense="The Lord appeared unto him, and said, Go not down into Egypt; dwell in the land which I shall tell thee of: sojourn in this land, and I will be with thee, and will bless thee. And Isaac dwelt in Gerar. When the herdmen of Gerar strove with him for the wells he dug, he removed and digged another rather than fight for what was his.",
  judgment="Then Isaac sowed in that land, and received in the same year an hundredfold: and the Lord blessed him. And the man waxed great, and went forward, and grew until he became very great. At Beer-sheba the Lord appeared to him the same night: fear not, for I am with thee, and will bless thee, and multiply thy seed for my servant Abraham's sake. Abimelech came to him to make a covenant, saying, We saw certainly that the Lord was with thee.",
  refs=[R("Genesis",26,"1-6"),R("Genesis",26,"12-14"),R("Genesis",26,"17-22"),R("Genesis",26,"23-25"),R("Genesis",26,"26-29"),R("Hebrews",11,"9")],
  laws=["2H","2B","3I"], topics=["obedience","trust-god","egypt","peace"], themes=["obedience","faith","provision","peace"]),

 B(slug="joseph", name="Joseph", era="Patriarchal", charge="Refusing his master's wife: how can I do this great wickedness, and sin against God?",
  summary="Sold by his brothers, bought by Potiphar, tempted daily by his master's wife, Joseph refused, fled, and was jailed on her lie. The Lord was with him in the pit, in the prison, and in the palace, and he became the man through whom the whole house of Israel was kept alive.",
  offense="His master's wife cast her eyes upon Joseph; and she said, Lie with me. But he refused: Behold, my master wotteth not what is with me in the house; how then can I do this great wickedness, and sin against God? She spake to Joseph day by day, and he hearkened not unto her. When she caught him by his garment, he left his garment in her hand, and fled. Years later he told his brothers: ye thought evil against me; but God meant it unto good.",
  judgment="The Lord was with Joseph, and he was a prosperous man. The keeper of the prison committed to Joseph's hand all the prisoners, because the Lord was with him, and that which he did, the Lord made it to prosper. Pharaoh said, Thou shalt be over my house, and according unto thy word shall all my people be ruled. The psalm: the word of the Lord tried him; the king sent and loosed him, and made him lord of his house. Wisdom: she delivered him not, but brought him the sceptre of the kingdom.",
  refs=[R("Genesis",39,"1-6"),R("Genesis",39,"7-12"),R("Genesis",39,"20-23"),R("Genesis",41,"38-44"),R("Genesis",50,"19-21"),R("Psalms",105,"17-22"),R("Wisdom of Solomon",10,"13-14"),R("Sirach",49,"15")],
  laws=["5D","12A","2C","21C"], topics=["adultery","sexual-lust","fear-god","our-servants"], themes=["chastity","faith","provision","deliverance","obedience"]),

 B(slug="job", name="Job", era="Patriarchal", charge="Perfect and upright, fearing God and eschewing evil; sinning not with his lips in all his loss",
  summary="The Lord himself gave the character: there is none like him in the earth. He lost his oxen, his sheep, his camels, his servants, his ten children and his health in a day and a night, and said, Blessed be the name of the Lord. The Lord turned his captivity, and gave him twice as much as he had before.",
  offense="That man was perfect and upright, and one that feared God, and eschewed evil. He rose up early in the morning and offered burnt offerings for his children, lest they had sinned. When all was taken he fell down upon the ground and worshipped: the Lord gave, and the Lord hath taken away; blessed be the name of the Lord. In all this Job sinned not, nor charged God foolishly. His own account of the law he kept: I delivered the poor that cried, and the fatherless; I was eyes to the blind, and feet was I to the lame; I made a covenant with mine eyes.",
  judgment="The Lord turned the captivity of Job, when he prayed for his friends: also the Lord gave Job twice as much as he had before. So the Lord blessed the latter end of Job more than his beginning. He had fourteen thousand sheep, six thousand camels, seven sons and three daughters, and in all the land were no women found so fair as the daughters of Job; and he saw his sons' sons, even four generations. James: ye have heard of the patience of Job, and have seen the end of the Lord; that the Lord is very pitiful, and of tender mercy.",
  refs=[R("Job",1,"1-5"),R("Job",1,"8"),R("Job",1,"20-22"),R("Job",2,"3"),R("Job",29,"11-17"),R("Job",31,"1"),R("Job",42,"10-17"),R("James",5,"11"),R("Ezekiel",14,"14")],
  laws=["2C","17E","15B","15C","12A"], topics=["fear-god","patience","poor","trials"], themes=["faith","patience","restoration","provision"]),

 # ---------------- Egypt ----------------
 B(slug="shiphrah-and-puah", name="Shiphrah and Puah, the midwives", era="Egypt", charge="Fearing God and not doing as the king of Egypt commanded them",
  summary="Pharaoh ordered the Hebrew midwives to kill every son at the birthstool. They feared God more than the king and saved the men children alive. God dealt well with them, and because they feared God, he made them houses.",
  offense="The king of Egypt spake to the Hebrew midwives, Shiphrah and Puah: when ye do the office of a midwife to the Hebrew women, if it be a son, then ye shall kill him. But the midwives feared God, and did not as the king of Egypt commanded them, but saved the men children alive. Called to account, they answered him and the killing did not pass through their hands.",
  judgment="Therefore God dealt well with the midwives: and the people multiplied, and waxed very mighty. And it came to pass, because the midwives feared God, that he made them houses. Two women's names are written; Pharaoh's is not.",
  refs=[R("Exodus",1,"15-17"),R("Exodus",1,"18-21"),R("Acts",5,"29"),R("Proverbs",24,"11-12"),R("Psalms",112,"1-3")],
  laws=["2C","10A","15C","4A"], topics=["fear-god","murder","abortion","submission"], themes=["faith","courage","deliverance","provision"]),

 B(slug="moses", name="Moses", era="Egypt", charge="Refusing to be called the son of Pharaoh's daughter; faithful in all the Lord's house; very meek, above all the men upon the face of the earth",
  summary="He gave up the court of Egypt to be counted with slaves, and led them forty years through a wilderness that murmured against him at every turn. The Lord's testimony on him is unmatched: my servant Moses, who is faithful in all mine house; with him will I speak mouth to mouth. He was buried by God.",
  offense="By faith Moses, when he was come to years, refused to be called the son of Pharaoh's daughter; choosing rather to suffer affliction with the people of God, than to enjoy the pleasures of sin for a season. Now the man Moses was very meek, above all the men which were upon the face of the earth. When the Lord offered to make of him a great nation instead of Israel, he pleaded for the people and asked to be blotted out of the book rather than that they be. According to all that the Lord commanded Moses, so did he: the whole tabernacle, and Moses blessed them.",
  judgment="With him will I speak mouth to mouth, even apparently, and not in dark speeches; and the similitude of the Lord shall he behold. The Lord spake unto Moses face to face, as a man speaketh unto his friend. Sirach: he made him glorious in the sight of kings, and gave him commandments before his people, and shewed him part of his glory; he sanctified him in his faithfulness and meekness, and chose him out of all men. His eye was not dim, nor his natural force abated at a hundred and twenty; and there arose not a prophet since in Israel like unto Moses.",
  refs=[R("Hebrews",11,"24-27"),R("Numbers",12,"3"),R("Numbers",12,"6-8"),R("Exodus",33,"11"),R("Exodus",32,"30-32"),R("Exodus",39,"42-43"),R("Deuteronomy",34,"5-12"),R("Sirach",45,"1-5"),R("Matthew",17,"3")],
  laws=["2H","17I","20A","13D"], topics=["obedience","meek","humility","suffering"], themes=["faith","obedience","leadership","meekness"]),

 B(slug="israel-at-the-first-passover", name="Israel at the first Passover", era="Egypt", charge="Doing as the Lord commanded Moses and Aaron: the lamb, the blood on the door, the unleavened bread",
  summary="On the night the destroyer went through Egypt, every house of Israel that did as it was told was passed over. The children of Israel went away, and did as the Lord had commanded Moses and Aaron, so did they. The ordinance was made perpetual on the spot.",
  offense="Take you a lamb according to the house of your fathers; kill it in the evening; take of the blood and strike it on the two side posts and on the upper door post; eat it with unleavened bread and bitter herbs, in haste; none of you shall go out at the door of his house until the morning. And the children of Israel went away, and did as the Lord had commanded Moses and Aaron, so did they. By faith he kept the passover, and the sprinkling of blood, lest he that destroyed the firstborn should touch them.",
  judgment="The blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you. At midnight the Lord smote all the firstborn in the land of Egypt, and against the children of Israel not so much as a dog moved his tongue. He brought them forth also with silver and gold: and there was not one feeble person among their tribes. Thus did all the children of Israel; as the Lord commanded Moses and Aaron, so did they. And it came to pass the selfsame day.",
  refs=[R("Exodus",12,"3-13"),R("Exodus",12,"21-28"),R("Exodus",12,"29-36"),R("Exodus",12,"50-51"),R("Exodus",11,"7"),R("Psalms",105,"36-38"),R("Hebrews",11,"28")],
  laws=["9A","9B","2H","2B"], topics=["passover","passover-lamb","obedience","unleavened-bread"], themes=["obedience","deliverance","covenant","feasts"]),

 # ---------------- Wilderness ----------------
 B(slug="the-sons-of-levi-at-the-calf", name="The sons of Levi at the golden calf", era="Wilderness", charge="Answering, Who is on the Lord's side? and executing the sentence on their own brethren",
  summary="When Moses stood in the gate of the camp and asked who was on the Lord's side, all the sons of Levi gathered to him, took their swords, and went through the camp. Three thousand fell. For that day the priesthood and the service of the sanctuary were given to the tribe, and Moses' last blessing names it.",
  offense="Moses stood in the gate of the camp, and said, Who is on the Lord's side? let him come unto me. And all the sons of Levi gathered themselves together unto him. Put every man his sword by his side, and slay every man his brother, and every man his companion, and every man his neighbour. And the children of Levi did according to the word of Moses. Deuteronomy: who said unto his father and to his mother, I have not seen him; neither did he acknowledge his brethren, nor knew his own children: for they have observed thy word, and kept thy covenant.",
  judgment="Consecrate yourselves to day to the Lord, even every man upon his son, and upon his brother; that he may bestow upon you a blessing this day. Of Levi he said, Let thy Thummim and thy Urim be with thy holy one; they shall teach Jacob thy judgments, and Israel thy law: they shall put incense before thee, and whole burnt sacrifice upon thine altar. Bless, Lord, his substance, and accept the work of his hands. The tribe was taken instead of the firstborn of all Israel to keep the charge of the tabernacle.",
  refs=[R("Exodus",32,"25-29"),R("Deuteronomy",33,"8-11"),R("Numbers",3,"11-13"),R("Numbers",3,"40-45"),R("Malachi",2,"4-7"),R("Deuteronomy",13,"6-11")],
  laws=["2D","10F","20B","2J"], topics=["idolatry","tithes-for-levi","kings-and-priests","obedience"], themes=["zeal","priesthood","obedience","covenant"]),

 B(slug="caleb-and-joshua", name="Caleb and Joshua", era="Wilderness", charge="Wholly following the Lord when ten spies and the whole congregation would not",
  summary="Twelve men saw the same land, the same cities and the same giants. Ten said, We be not able. Two said, The Lord is with us: fear them not. The ten died of the plague; the whole generation died in the wilderness; and Caleb and Joshua were the only two of six hundred thousand who walked into the land.",
  offense="Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it. Joshua and Caleb rent their clothes and said, If the Lord delight in us, then he will bring us into this land; only rebel not ye against the Lord, neither fear ye the people of the land; for they are bread for us. The congregation bade stone them with stones. Forty-five years later Caleb could still say, I wholly followed the Lord my God.",
  judgment="But my servant Caleb, because he had another spirit with him, and hath followed me fully, him will I bring into the land whereinto he went; and his seed shall possess it. Doubtless ye shall not come into the land, save Caleb the son of Jephunneh, and Joshua the son of Nun. At eighty-five Caleb took Hebron, as strong that day as the day Moses sent him: because that he wholly followed the Lord God of Israel. Joshua led Israel over Jordan and divided the inheritance, and the Lord magnified him in the sight of all Israel.",
  refs=[R("Numbers",13,"30"),R("Numbers",14,"6-10"),R("Numbers",14,"24"),R("Numbers",14,"30"),R("Numbers",14,"36-38"),R("Deuteronomy",1,"34-38"),R("Joshua",14,"6-14"),R("Joshua",3,"7"),R("Sirach",46,"1-10")],
  laws=["2B","2H","22A","18A"], topics=["believe","obedience","giants","trust-god"], themes=["faith","courage","obedience","inheritance"]),

 B(slug="phinehas", name="Phinehas", era="Wilderness", charge="Zealous for his God at Peor; making an atonement for the children of Israel",
  summary="While the congregation wept at the door of the tabernacle and the plague was running, a prince of Simeon walked a Midianite woman into the camp in front of them. Phinehas took a javelin and went in after them, and the plague was stayed at twenty-four thousand. The Lord gave him the covenant of an everlasting priesthood.",
  offense="When Phinehas, the son of Eleazar, the son of Aaron the priest, saw it, he rose up from among the congregation, and took a javelin in his hand; and he went after the man of Israel into the tent, and thrust both of them through. So the plague was stayed from the children of Israel. The psalm: then stood up Phinehas, and executed judgment: and so the plague was stayed. And that was counted unto him for righteousness unto all generations for evermore.",
  judgment="Phinehas hath turned my wrath away from the children of Israel, while he was zealous for my sake among them, that I consumed not the children of Israel in my jealousy. Wherefore say, Behold, I give unto him my covenant of peace: and he shall have it, and his seed after him, even the covenant of an everlasting priesthood; because he was zealous for his God, and made an atonement for the children of Israel. Sirach and Mattathias both name him first among the zealous, and the high priesthood ran in his line to the captivity.",
  refs=[R("Numbers",25,"6-9"),R("Numbers",25,"10-13"),R("Psalms",106,"28-31"),R("Sirach",45,"23-25"),R("1 Maccabees",2,"54"),R("Joshua",22,"30-31")],
  laws=["5E","2D","20B","19E"], topics=["kings-and-priests","sexual-lust","obedience","judgement"], themes=["zeal","priesthood","covenant","obedience"]),

 B(slug="the-daughters-of-zelophehad", name="The daughters of Zelophehad", era="Wilderness", charge="Asking rightly for their father's inheritance, and marrying within their tribe as commanded",
  summary="Five sisters with no brother came to the door of the tabernacle and asked why their father's name should be done away from among his family because he had no son. The Lord said, The daughters of Zelophehad speak right, and made a statute of judgment for all Israel. They then married as they were told, and kept the inheritance in Manasseh.",
  offense="Mahlah, Noah, Hoglah, Milcah and Tirzah stood before Moses, and before Eleazar the priest, and before the princes and all the congregation, saying, Our father died in the wilderness, and was not in the company of them that gathered themselves together against the Lord in the company of Korah; but died in his own sin, and had no sons. Give unto us therefore a possession among the brethren of our father. When the heads of Manasseh asked that the inheritance not pass to another tribe by marriage, the Lord commanded them to marry within the family of their father's tribe; even as the Lord commanded Moses, so did the daughters of Zelophehad.",
  judgment="The daughters of Zelophehad speak right: thou shalt surely give them a possession of an inheritance among their father's brethren; and thou shalt cause the inheritance of their father to pass unto them. And it became a statute of judgment: if a man die, and have no son, then ye shall cause his inheritance to pass unto his daughter. Joshua and Eleazar gave them an inheritance among the brethren of their father, according to the commandment of the Lord. Their names are written four times in the law and the histories.",
  refs=[R("Numbers",27,"1-7"),R("Numbers",27,"8-11"),R("Numbers",36,"5-12"),R("Joshua",17,"3-6"),R("1 Chronicles",7,"15")],
  laws=["6E","18A","19A","5G"], topics=["heritage","women-in-order","justice","marriage"], themes=["inheritance","justice","obedience","family"]),

 # ---------------- Conquest ----------------
 B(slug="rahab", name="Rahab", era="Conquest", charge="Receiving the spies with peace, and believing that the Lord had given Israel the land",
  summary="A harlot of Jericho hid two Israelite spies under the flax on her roof, confessed that the Lord their God is God in heaven above and in earth beneath, and asked for her father's house. She bound the scarlet line in the window. When the wall fell, hers was the one house left, and she is in the line of Christ.",
  offense="I know that the Lord hath given you the land, and that your terror is fallen upon us. For the Lord your God, he is God in heaven above, and in earth beneath. Now therefore, I pray you, swear unto me by the Lord, since I have shewed you kindness, that ye will also shew kindness unto my father's house. She let them down by a cord through the window, and bound the scarlet line in the window as they said. James: was not Rahab the harlot justified by works, when she had received the messengers, and had sent them out another way?",
  judgment="Joshua saved Rahab the harlot alive, and her father's household, and all that she had; and she dwelleth in Israel even unto this day. By faith the harlot Rahab perished not with them that believed not, when she had received the spies with peace. Salmon begat Booz of Rachab; and Booz begat Obed of Ruth; and Obed begat Jesse; and Jesse begat David the king.",
  refs=[R("Joshua",2,"1-7"),R("Joshua",2,"8-14"),R("Joshua",2,"17-21"),R("Joshua",6,"22-25"),R("Hebrews",11,"31"),R("James",2,"25"),R("Matthew",1,"5")],
  laws=["2B","15A","4D","11B"], topics=["believe","strangers","agreement","deliverance"], themes=["faith","hospitality","deliverance","covenant"]),

 # ---------------- Judges ----------------
 B(slug="gideon", name="Gideon", era="Judges", charge="Throwing down the altar of Baal in his father's house; going against Midian with three hundred, as the Lord said",
  summary="Threshing wheat in a winepress to hide it from the Midianites, the least in his father's house was called a mighty man of valour. He cut down Baal's altar by night, sent home thirty-one thousand seven hundred men because the Lord said the army was too big, and broke the Midianites with pitchers, lamps and trumpets.",
  offense="Throw down the altar of Baal that thy father hath, and cut down the grove that is by it: and build an altar unto the Lord thy God. Then Gideon took ten men of his servants, and did as the Lord had said unto him. The Lord said, The people that are with thee are too many; and Gideon sent home all that were fearful, and then all but three hundred, and went down against a host like grasshoppers for multitude with the men who lapped. They cried, The sword of the Lord, and of Gideon.",
  judgment="The Lord looked upon him, and said, Go in this thy might, and thou shalt save Israel from the hand of the Midianites: have not I sent thee? The Lord set every man's sword against his fellow throughout all the host, and Midian was subdued before the children of Israel, so that they lifted up their heads no more. And the country was in quietness forty years in the days of Gideon. His name stands in the roll of faith: who through faith subdued kingdoms, out of weakness were made strong. The ephod he made afterward is its own case.",
  refs=[R("Judges",6,"11-16"),R("Judges",6,"25-28"),R("Judges",7,"2-8"),R("Judges",7,"16-22"),R("Judges",8,"28"),R("Hebrews",11,"32-34"),R("Deuteronomy",20,"1-4")],
  laws=["2D","22B","2B","2H"], topics=["idolatry","army","believe","deliverance"], themes=["faith","courage","deliverance","obedience","war"]),

 B(slug="jael", name="Jael", era="Judges", charge="Blessed above women in the tent: the nail, the hammer, and Sisera",
  summary="Sisera fled on foot to the tent of Heber the Kenite, whose house was at peace with Jabin. Jael covered him with a mantle, gave him milk, and when he slept drove a tent nail through his temples into the ground. Deborah's song puts the blessing on her twice over.",
  offense="Jael went out to meet Sisera, and said unto him, Turn in, my lord, turn in to me; fear not. He asked water and she gave him milk, and covered him. Then Jael Heber's wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died. She had chosen Israel's side over her husband's peace with the oppressor.",
  judgment="Blessed above women shall Jael the wife of Heber the Kenite be, blessed shall she be above women in the tent. She put her hand to the nail, and her right hand to the workmen's hammer; and with the hammer she smote Sisera, she smote off his head. So let all thine enemies perish, O Lord: but let them that love him be as the sun when he goeth forth in his might. And the land had rest forty years.",
  refs=[R("Judges",4,"17-22"),R("Judges",5,"24-27"),R("Judges",5,"31"),R("Judges",4,"9"),R("Psalms",83,"9-12")],
  laws=["22D","11A","2E"], topics=["our-enemies","deliverance","women-in-order"], themes=["courage","deliverance","war","zeal"]),

 B(slug="ruth-and-boaz", name="Ruth and Boaz", era="Judges", charge="Ruth: cleaving to Naomi and to Naomi's God. Boaz: the law of gleaning, and the law of the kinsman, done to the letter",
  summary="A Moabite widow left her people for a mother in law with nothing, and said, thy people shall be my people, and thy God my God. A man of Bethlehem let her glean, ordered handfuls dropped on purpose, and then went to the gate and redeemed her under the law before ten elders. Their son was Obed, the father of Jesse, the father of David.",
  offense="Ruth: Intreat me not to leave thee; whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God. Boaz to Ruth: It hath fully been shewed me, all that thou hast done unto thy mother in law since the death of thine husband. Boaz to his reapers: Let fall also some of the handfuls of purpose for her. At the gate: The day thou buyest the field of the hand of Naomi, thou must buy it also of Ruth the Moabitess, the wife of the dead, to raise up the name of the dead upon his inheritance. And the near kinsman drew off his shoe.",
  judgment="The Lord recompense thy work, and a full reward be given thee of the Lord God of Israel, under whose wings thou art come to trust. The Lord make the woman that is come into thine house like Rachel and like Leah, which two did build the house of Israel. So Boaz took Ruth, and she was his wife; and the Lord gave her conception, and she bare a son. Blessed be the Lord, which hath not left thee this day without a kinsman, that his name may be famous in Israel. They called his name Obed: he is the father of Jesse, the father of David.",
  refs=[R("Ruth",1,"16-17"),R("Ruth",2,"8-12"),R("Ruth",2,"15-16"),R("Ruth",3,"10-13"),R("Ruth",4,"1-10"),R("Ruth",4,"11-17"),R("Leviticus",19,"9-10"),R("Deuteronomy",25,"5-6"),R("Matthew",1,"5-6")],
  laws=["15E","15C","6E","5A","15A"], topics=["poor","strangers","marriage","buy-redeem-save","chosen"], themes=["hospitality","faith","inheritance","family","provision"]),

 B(slug="hannah", name="Hannah", era="Judges", charge="Praying in bitterness of soul, vowing a son to the Lord, and giving him when she had him",
  summary="Barren, provoked yearly by her rival, mistaken for a drunkard by the high priest, she poured out her soul before the Lord and vowed that if he gave her a son she would give him back for all his days. He did, and she did: she brought Samuel to Shiloh as soon as he was weaned. The Lord gave her five more.",
  offense="She vowed a vow, and said, O Lord of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and give unto thine handmaid a man child, then I will give him unto the Lord all the days of his life. When he was weaned she took him up with three bullocks and brought him unto the house of the Lord in Shiloh: for this child I prayed; therefore also I have lent him to the Lord; as long as he liveth he shall be lent to the Lord. The law of vows: when thou vowest a vow unto the Lord thy God, thou shalt not slack to pay it.",
  judgment="Eli answered, Go in peace: and the God of Israel grant thee thy petition. The Lord remembered her, and she bare a son, and called his name Samuel. Her song: my heart rejoiceth in the Lord; the barren hath born seven. And the Lord visited Hannah, so that she conceived, and bare three sons and two daughters. And the child Samuel grew before the Lord, and all Israel from Dan to Beer-sheba knew that Samuel was established to be a prophet of the Lord.",
  refs=[R("1 Samuel",1,"9-18"),R("1 Samuel",1,"19-20"),R("1 Samuel",1,"24-28"),R("1 Samuel",2,"1-10"),R("1 Samuel",2,"18-21"),R("1 Samuel",3,"19-21"),R("Deuteronomy",23,"21-23")],
  laws=["4D","2N","20E"], topics=["prayer","agreement","giving","mothers-day"], themes=["prayer","faith","covenant","family","provision"]),

 # ---------------- United Monarchy ----------------
 B(slug="david", name="David", era="United Monarchy", charge="A man after the Lord's own heart; keeping his commandments and following him with all his heart, save only in the matter of Uriah",
  summary="Shepherd, giant-killer, hunted man who twice had Saul in his hand and would not touch the Lord's anointed, king who danced before the ark and would not build a house until told he could. The Lord made a covenant with his house that has a Son sitting on it for ever. His one great fall is its own case; this is the rest.",
  offense="The Lord hath sought him a man after his own heart. The Lord forbid that I should do this thing unto my master, the Lord's anointed, to stretch forth mine hand against him. He judged and did justice unto all his people. Because David did that which was right in the eyes of the Lord, and turned not aside from any thing that he commanded him all the days of his life, save only in the matter of Uriah the Hittite. His own words: I have kept the ways of the Lord, and have not wickedly departed from my God. For all his judgments were before me, and I did not put away his statutes from me.",
  judgment="Thine house and thy kingdom shall be established for ever before thee: thy throne shall be established for ever. Therefore the Lord rewarded me according to my righteousness; according to the cleanness of my hands in his eyesight. The sure mercies of David. He gave them a king, David, to whom also he gave testimony, and said, I have found David the son of Jesse, a man after mine own heart, which shall fulfil all my will. Of this man's seed hath God according to his promise raised unto Israel a Saviour, Jesus.",
  refs=[R("1 Samuel",13,"14"),R("1 Samuel",24,"4-7"),R("1 Samuel",26,"9-11"),R("2 Samuel",7,"8-16"),R("2 Samuel",8,"15"),R("1 Kings",15,"5"),R("Psalms",18,"20-24"),R("Isaiah",55,"3"),R("Acts",13,"22-23"),R("Sirach",47,"2-11")],
  laws=["8A","8D","2E","4F","2J"], topics=["david-as-king","kings-and-priests","obedience","justice","tabernacle-of-david"], themes=["kingship","covenant","obedience","faith","justice"]),

 B(slug="abigail", name="Abigail", era="United Monarchy", charge="Keeping David from shedding blood and avenging himself with his own hand",
  summary="Her husband Nabal railed on David's men; David strapped on his sword to kill every male of the house by morning. Abigail met him on the road with two hundred loaves and a speech that is one of the wisest in scripture, and turned him back. Ten days later the Lord smote Nabal, and David sent for her.",
  offense="Abigail made haste, and took two hundred loaves, and two bottles of wine, and five sheep ready dressed, and fell before David on her face: Now therefore, my lord, as the Lord liveth, seeing the Lord hath withholden thee from coming to shed blood, and from avenging thyself with thine own hand. The Lord will certainly make my lord a sure house; because my lord fighteth the battles of the Lord, and evil hath not been found in thee all thy days. That this shall be no grief unto thee, nor offence of heart unto my lord, that thou hast shed blood causeless.",
  judgment="David said to Abigail, Blessed be the Lord God of Israel, which sent thee this day to meet me: and blessed be thy advice, and blessed be thou, which hast kept me this day from coming to shed blood, and from avenging myself with mine own hand. When Nabal was dead, David sent and communed with Abigail, to take her to him to wife; and she became his wife, and bore him Chileab. The ill-married wife of a churl became the wife of the king, for a wise word spoken in time.",
  refs=[R("1 Samuel",25,"14-19"),R("1 Samuel",25,"23-31"),R("1 Samuel",25,"32-35"),R("1 Samuel",25,"36-42"),R("2 Samuel",3,"3"),R("Proverbs",15,"1"),R("Romans",12,"19")],
  laws=["17M","10A","12F","5C"], topics=["avenge","wisdom","wife","peace"], themes=["wisdom","mercy","peace","family"]),

 B(slug="obed-edom", name="Obed-edom the Gittite", era="United Monarchy", charge="Keeping the ark of God in his house three months, after it had killed Uzzah",
  summary="Uzzah had just died for touching the ark, and David was afraid to bring it into the city. It went instead into the house of Obed-edom of Gath, and stayed three months. The Lord blessed him and all his household so visibly that David heard of it and came back for the ark with sacrifices and dancing.",
  offense="David was afraid of the Lord that day, and said, How shall the ark of the Lord come to me? So David would not remove the ark of the Lord unto him into the city of David: but David carried it aside into the house of Obed-edom the Gittite. He took in what the king was afraid of, and kept it as it was meant to be kept.",
  judgment="And the ark of the Lord continued in the house of Obed-edom the Gittite three months: and the Lord blessed Obed-edom, and all his household. It was told king David, saying, The Lord hath blessed the house of Obed-edom, and all that pertaineth unto him, because of the ark of God. The Chronicles count him afterward among the porters and the singers before the ark, with eight sons and sixty-two able men of his house: for God blessed him.",
  refs=[R("2 Samuel",6,"6-11"),R("2 Samuel",6,"12"),R("1 Chronicles",13,"13-14"),R("1 Chronicles",26,"4-8"),R("1 Chronicles",15,"24-25"),R("Psalms",128,"1-4")],
  laws=["2C","2J","20D"], topics=["ark-of-covenant","fear-god","kings-and-priests"], themes=["faith","provision","family","priesthood"]),

 B(slug="solomon-at-gibeon", name="Solomon at Gibeon", era="United Monarchy", charge="Asking for an understanding heart to judge the people, and not for long life, riches, or the life of his enemies",
  summary="Offered anything he wanted, the young king asked for wisdom to judge a great people. The speech pleased the Lord, who gave him the wisdom and added the riches and honour he had not asked. The kingdom he built on it was the greatest Israel ever had. What he did with his wives afterward is another case.",
  offense="Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people? And the speech pleased the Lord, that Solomon had asked this thing. In Wisdom: I called upon God, and the spirit of wisdom came to me; I preferred her before sceptres and thrones, and esteemed riches nothing in comparison of her.",
  judgment="Because thou hast asked this thing, and hast not asked for thyself long life; neither hast asked riches for thyself, nor hast asked the life of thine enemies; but hast asked for thyself understanding to discern judgment; behold, I have done according to thy words: lo, I have given thee a wise and an understanding heart; so that there was none like thee before thee, neither after thee shall any arise like unto thee. And I have also given thee that which thou hast not asked, both riches, and honour. All the earth sought to Solomon, to hear his wisdom, which God had put in his heart.",
  refs=[R("1 Kings",3,"5-9"),R("1 Kings",3,"10-14"),R("1 Kings",4,"29-34"),R("1 Kings",10,"23-24"),R("2 Chronicles",1,"7-12"),R("Wisdom of Solomon",7,"7-14"),R("James",1,"5")],
  laws=["8A","4F","2N","19B"], topics=["wisdom","prayer","kings-and-priests","justice"], themes=["wisdom","kingship","prayer","provision"]),

 B(slug="barzillai", name="Barzillai the Gileadite", era="United Monarchy", charge="Bringing beds, wheat, and honey to the king and his hungry men in the wilderness at Mahanaim",
  summary="When David fled from Absalom, an old man of Rogelim brought provision for the king and the people with him, saying, The people is hungry, and weary, and thirsty, in the wilderness. David wanted to keep him at court for life. Barzillai was eighty and asked only to die in his own city; David took his son instead, and charged Solomon on his deathbed to remember the house.",
  offense="Barzillai the Gileadite of Rogelim brought beds, and basons, and earthen vessels, and wheat, and barley, and flour, and parched corn, and beans, and lentiles, and honey, and butter, and sheep, and cheese of kine, for David, and for the people that were with him, to eat: for they said, The people is hungry, and weary, and thirsty, in the wilderness. He had provided the king of sustenance while he lay at Mahanaim; for he was a very great man.",
  judgment="The king said unto Barzillai, Come thou over with me, and I will feed thee with me in Jerusalem. Chimham shall go over with me, and I will do to him that which shall seem good unto thee: and whatsoever thou shalt require of me, that will I do for thee. And the king kissed Barzillai, and blessed him. David to Solomon: shew kindness unto the sons of Barzillai the Gileadite, and let them be of those that eat at thy table: for so they came to me when I fled because of Absalom thy brother. Centuries later his family was still known by his name.",
  refs=[R("2 Samuel",17,"27-29"),R("2 Samuel",19,"31-39"),R("1 Kings",2,"7"),R("Ezra",2,"61"),R("Matthew",25,"34-40"),R("Hebrews",6,"10")],
  laws=["15A","11B","8D","12F"], topics=["giving","poor","kings-and-priests"], themes=["hospitality","loyalty","provision","kingship"]),

 # ---------------- Divided Kingdom ----------------
 B(slug="asa-in-his-first-years", name="Asa in his first years", era="Divided Kingdom", charge="Taking away the strange altars and the high places; commanding Judah to seek the Lord and do the law; crying to the Lord against a million Ethiopians",
  summary="Before the failure that is its own case, Asa did thirty-five years of what a king was for. He removed the idols, removed his own mother from being queen for her grove, made Judah swear to seek the Lord with all their heart, and when Zerah came against him with a million men he prayed one prayer and won.",
  offense="Asa did that which was good and right in the eyes of the Lord his God: for he took away the altars of the strange gods, and the high places, and brake down the images, and cut down the groves: and commanded Judah to seek the Lord God of their fathers, and to do the law and the commandment. Asa cried unto the Lord his God, and said, Lord, it is nothing with thee to help, whether with many, or with them that have no power: help us, O Lord our God; for we rest on thee. And also concerning Maachah his mother, he removed her from being queen, because she had made an idol in a grove.",
  judgment="So the Lord smote the Ethiopians before Asa, and before Judah; and the Ethiopians fled. The Lord is with you, while ye be with him; and if ye seek him, he will be found of you. They sware unto the Lord, and all Judah rejoiced at the oath: and the Lord was found of them, and gave them rest round about. And there was no more war unto the five and thirtieth year of the reign of Asa.",
  refs=[R("2 Chronicles",14,"1-7"),R("2 Chronicles",14,"9-15"),R("2 Chronicles",15,"1-8"),R("2 Chronicles",15,"12-19"),R("1 Kings",15,"11-15")],
  laws=["2D","8A","2J","4D","6B"], topics=["idolatry","seek-the-lord","kings-and-priests","trust-god"], themes=["kingship","obedience","faith","peace","covenant"]),

 B(slug="jehoshaphat", name="Jehoshaphat", era="Divided Kingdom", charge="Seeking the Lord and walking in his commandments; sending Levites to teach the book of the law through all the cities of Judah; setting the battle in array with singers",
  summary="He sent princes and Levites round Judah with the book of the law to teach it, and the fear of the Lord fell on the kingdoms round about. When Moab, Ammon and Edom came against him he proclaimed a fast, prayed in the congregation, and put the singers in front of the army. They came to the watchtower and found only dead bodies. His alliances with Ahab's house are their own case.",
  offense="The Lord was with Jehoshaphat, because he walked in the first ways of his father David, and sought not unto Baalim; but sought to the Lord God of his father, and walked in his commandments. He sent to his princes, and with them the Levites, and they taught in Judah, and had the book of the law of the Lord with them, and went about throughout all the cities of Judah, and taught the people. Before the battle: O our God, wilt thou not judge them? for we have no might against this great company; neither know we what to do: but our eyes are upon thee. He appointed singers unto the Lord, that should praise the beauty of holiness, as they went out before the army.",
  judgment="Therefore the Lord stablished the kingdom in his hand; and all Judah brought to Jehoshaphat presents; and he had riches and honour in abundance. And the fear of the Lord fell upon all the kingdoms of the lands that were round about Judah, so that they made no war against Jehoshaphat. Ye shall not need to fight in this battle: set yourselves, stand ye still, and see the salvation of the Lord with you. When they began to sing and to praise, the Lord set ambushments, and they were smitten. They were three days in gathering of the spoil, it was so much. So the realm of Jehoshaphat was quiet: for his God gave him rest round about.",
  refs=[R("2 Chronicles",17,"3-6"),R("2 Chronicles",17,"7-10"),R("2 Chronicles",20,"3-13"),R("2 Chronicles",20,"14-17"),R("2 Chronicles",20,"20-26"),R("2 Chronicles",20,"27-30"),R("Deuteronomy",6,"6-9")],
  laws=["4B","6D","8A","2N","22A","2M"], topics=["kings-and-priests","study","prayer","fasting","trust-god"], themes=["kingship","obedience","prayer","deliverance","teaching"]),

 B(slug="the-widow-of-zarephath", name="The widow of Zarephath", era="Divided Kingdom", charge="Making the prophet's cake first, out of the last handful of meal",
  summary="A Gentile widow gathering two sticks to cook a last meal for herself and her son was asked by a stranger to feed him first from it, on a promise from the God of Israel. She did. The barrel of meal did not waste and the cruse of oil did not fail until the rain came, and when her son died the prophet raised him.",
  offense="As the Lord thy God liveth, I have not a cake, but an handful of meal in a barrel, and a little oil in a cruse: and, behold, I am gathering two sticks, that I may go in and dress it for me and my son, that we may eat it, and die. Elijah said, Fear not; go and do as thou hast said: but make me thereof a little cake first, and bring it unto me, and after make for thee and for thy son. And she went and did according to the saying of Elijah. Christ named her against Nazareth: unto none of the widows of Israel was Elias sent, save unto Sarepta.",
  judgment="For thus saith the Lord God of Israel, The barrel of meal shall not waste, neither shall the cruse of oil fail, until the day that the Lord sendeth rain upon the earth. And she, and he, and her house, did eat many days. When her son fell sick and there was no breath left in him, Elijah stretched himself upon the child three times and cried unto the Lord, and the Lord heard the voice of Elijah; and the soul of the child came into him again, and he revived. The woman said, Now by this I know that thou art a man of God, and that the word of the Lord in thy mouth is truth.",
  refs=[R("1 Kings",17,"8-12"),R("1 Kings",17,"13-16"),R("1 Kings",17,"17-24"),R("Luke",4,"25-26"),R("Matthew",10,"41-42"),R("Hebrews",11,"35")],
  laws=["15A","2B","20A"], topics=["strangers","believe","poor","giving"], themes=["faith","hospitality","provision","healing"]),

 B(slug="the-prophets-widow-and-the-oil", name="The prophet's widow, and the pot of oil", era="Divided Kingdom", charge="Borrowing not a few vessels, as the prophet said, and shutting the door",
  summary="A widow of the sons of the prophets had a creditor coming to take her two sons for bondmen and one pot of oil in the house. Elisha told her to borrow empty vessels, not a few, shut the door, and pour. The oil stopped when the vessels did. She paid the debt and lived on the rest.",
  offense="Go, borrow thee vessels abroad of all thy neighbours, even empty vessels; borrow not a few. And when thou art come in, thou shalt shut the door upon thee and upon thy sons, and shalt pour out into all those vessels. So she went from him, and shut the door upon her and upon her sons, who brought the vessels to her; and she poured out. The measure of the miracle was the measure of her borrowing.",
  judgment="It came to pass, when the vessels were full, that she said unto her son, Bring me yet a vessel. And he said unto her, There is not a vessel more. And the oil stayed. Then she came and told the man of God. And he said, Go, sell the oil, and pay thy debt, and live thou and thy children of the rest. The law against selling a brother into bondage for debt and the promise to the widow met in one pot of oil.",
  refs=[R("2 Kings",4,"1-4"),R("2 Kings",4,"5-7"),R("Leviticus",25,"39-41"),R("Deuteronomy",10,"18"),R("Psalms",68,"5"),R("Mark",6,"41-44")],
  laws=["15C","16A","2B"], topics=["poor","believe","obedience"], themes=["faith","provision","obedience","family"]),

 B(slug="the-shunammite", name="The Shunammite woman", era="Divided Kingdom", charge="Constraining the man of God to eat bread; building him a little chamber on the wall, with a bed, a table, a stool, and a candlestick",
  summary="A great woman of Shunem noticed that a holy man of God passed by continually and made him a room. She asked nothing. She was given a son; when he died on her knees she laid him on the prophet's bed, saddled the ass, and said, It is well. He was raised. Years later, back from a famine, she got her whole house and land restored by the king in one morning.",
  offense="She said unto her husband, Behold now, I perceive that this is an holy man of God, which passeth by us continually. Let us make a little chamber, I pray thee, on the wall; and let us set for him there a bed, and a table, and a stool, and a candlestick. Asked what could be done for her, she answered, I dwell among mine own people. When the child was dead she said to her husband and to Gehazi, It is well, and did not stop until she caught the prophet by the feet.",
  judgment="About this season, according to the time of life, thou shalt embrace a son. And the woman conceived, and bare a son at that season. The child sneezed seven times, and the child opened his eyes; and Elisha said, Take up thy son. Then she went in, and fell at his feet, and bowed herself to the ground, and took up her son. After seven years' famine she came to cry to the king for her house and land at the very moment Gehazi was telling him how Elisha had restored a dead body to life; and the king appointed an officer: Restore all that was hers, and all the fruits of the field since the day that she left the land, even until now.",
  refs=[R("2 Kings",4,"8-13"),R("2 Kings",4,"14-17"),R("2 Kings",4,"18-30"),R("2 Kings",4,"32-37"),R("2 Kings",8,"1-6"),R("Hebrews",11,"35"),R("Hebrews",13,"2")],
  laws=["15A","20A","18A","2B"], topics=["giving","believe","kings-and-priests","heritage"], themes=["hospitality","faith","healing","restoration","family"]),

 B(slug="naaman", name="Naaman the Syrian", era="Divided Kingdom", charge="Going down and dipping himself seven times in Jordan, according to the saying of the man of God, after his anger",
  summary="Captain of the host of Syria, a mighty man of valour, and a leper. He came with horses and chariots and a letter from his king, and was sent to wash in Jordan by a messenger who did not come to the door. He went away in a rage, was talked round by his servants, obeyed, and came up with the flesh of a little child. He went home with two mules' burden of earth and a vow to sacrifice to no other god.",
  offense="Naaman was wroth: Behold, I thought, He will surely come out to me, and stand, and call on the name of the Lord his God. Are not Abana and Pharpar, rivers of Damascus, better than all the waters of Israel? His servants said, If the prophet had bid thee do some great thing, wouldest thou not have done it? how much rather then, when he saith to thee, Wash, and be clean? Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God. He refused nothing afterward: thy servant will henceforth offer neither burnt offering nor sacrifice unto other gods, but unto the Lord.",
  judgment="His flesh came again like unto the flesh of a little child, and he was clean. And he returned to the man of God, he and all his company, and came, and stood before him: and he said, Behold, now I know that there is no God in all the earth, but in Israel. Christ named him against Nazareth: many lepers were in Israel in the time of Eliseus the prophet; and none of them was cleansed, saving Naaman the Syrian. The servant who ran after him for a gift is his own case.",
  refs=[R("2 Kings",5,"1-5"),R("2 Kings",5,"9-12"),R("2 Kings",5,"13-14"),R("2 Kings",5,"15-19"),R("Luke",4,"27"),R("Leviticus",14,"1-9")],
  laws=["2H","17I","2D","14G"], topics=["obedience","humility","healing","other-gods"], themes=["obedience","humility","healing","faith"]),

 B(slug="jotham", name="Jotham", era="Divided Kingdom", charge="Preparing his ways before the Lord his God; not entering the temple as his father had",
  summary="Uzziah's son had watched his father go into the temple to burn incense and come out a leper. Jotham did what was right, and stayed out of the priests' place. The chronicler gives the cause of his strength in one line: he prepared his ways before the Lord his God.",
  offense="He did that which was right in the sight of the Lord, according to all that his father Uzziah did: howbeit he entered not into the temple of the Lord. He built the high gate of the house of the Lord, and on the wall of Ophel he built much. He fought with the king of the Ammonites and prevailed against them.",
  judgment="So Jotham became mighty, because he prepared his ways before the Lord his God. The children of Ammon gave him an hundred talents of silver, and ten thousand measures of wheat, and ten thousand of barley, the same year, and the second year, and the third. Sixteen years, and no judgment written.",
  refs=[R("2 Chronicles",27,"1-6"),R("2 Kings",15,"32-35"),R("2 Chronicles",26,"16-21"),R("Proverbs",16,"3"),R("Psalms",1,"1-3")],
  laws=["8A","20B","2H"], topics=["kings-and-priests","obedience","fear-god"], themes=["kingship","obedience","provision"]),

 B(slug="hezekiah", name="Hezekiah", era="Divided Kingdom", charge="Trusting in the Lord God of Israel; cleaving to him and keeping his commandments; breaking the brasen serpent; keeping the passover; spreading Sennacherib's letter before the Lord",
  summary="He opened the doors of the house of the Lord in the first month of his first year, kept a passover Jerusalem had not seen since Solomon, broke the brasen serpent of Moses because Israel burned incense to it, and prayed his way through Sennacherib and through a sentence of death. The one pride of his heart is its own case. This is the rest.",
  offense="He trusted in the Lord God of Israel; so that after him was none like him among all the kings of Judah, nor any that were before him. For he clave to the Lord, and departed not from following him, but kept his commandments, which the Lord commanded Moses. He brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it. And in every work that he began in the service of the house of God, and in the law, and in the commandments, to seek his God, he did it with all his heart. Hezekiah received the letter, and went up into the house of the Lord, and spread it before the Lord.",
  judgment="And the Lord was with him; and he prospered whithersoever he went forth. Then Isaiah sent to Hezekiah: that which thou hast prayed to me against Sennacherib king of Assyria I have heard. I will defend this city, to save it, for mine own sake, and for my servant David's sake. Of his sickness: I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years; and the shadow went back ten degrees. Thus the Lord saved Hezekiah and the inhabitants of Jerusalem, and guided them on every side; and he was magnified in the sight of all nations from thenceforth.",
  refs=[R("2 Kings",18,"1-7"),R("2 Chronicles",29,"1-11"),R("2 Chronicles",30,"1-5"),R("2 Chronicles",30,"18-27"),R("2 Chronicles",31,"20-21"),R("2 Kings",19,"14-19"),R("2 Kings",19,"32-35"),R("2 Kings",20,"1-7"),R("2 Chronicles",32,"20-23"),R("Sirach",48,"17-22")],
  laws=["2B","2H","2F","9A","2D","2N"], topics=["trust-god","keep-the-commandments","passover","prayer","graven-images"], themes=["kingship","faith","obedience","prayer","deliverance","healing"]),

 B(slug="jehoiada-the-priest", name="Jehoiada the priest", era="Divided Kingdom", charge="Hiding the king's son six years from Athaliah; making a covenant between the Lord, the king, and the people; doing good in Israel, both toward God and toward his house",
  summary="When Athaliah killed the seed royal, Jehoiada's wife stole the baby Joash out of the slaughter and the priest hid him in the house of the Lord six years. In the seventh he armed the Levites, crowned the boy, had Athaliah taken out and slain, tore down the house of Baal, and set the temple in order. He was buried among the kings.",
  offense="Jehoshabeath the daughter of the king took Joash the son of Ahaziah, and stole him from among the king's sons that were slain, and put him and his nurse in a bedchamber, and hid him from Athaliah. Jehoiada brought out the king's son, and put upon him the crown, and gave him the testimony, and made him king. And Jehoiada made a covenant between him, and between all the people, and between the king, that they should be the Lord's people. And all the people went to the house of Baal, and brake it down. And Jehoiada appointed the offices of the house of the Lord by the hand of the priests the Levites, whom David had distributed.",
  judgment="And all the people of the land rejoiced: and the city was quiet, after that they had slain Athaliah with the sword. And Joash did that which was right in the sight of the Lord all the days of Jehoiada the priest. Jehoiada waxed old, and was full of days when he died; an hundred and thirty years old was he when he died. And they buried him in the city of David among the kings, because he had done good in Israel, both toward God, and toward his house. What Joash did after Jehoiada died is his own case.",
  refs=[R("2 Chronicles",22,"10-12"),R("2 Chronicles",23,"1-11"),R("2 Chronicles",23,"12-21"),R("2 Chronicles",24,"1-2"),R("2 Chronicles",24,"15-16"),R("2 Kings",11,"17-20")],
  laws=["20A","8B","2D","10G","4D"], topics=["kings-and-priests","idolatry","agreement","david-as-king"], themes=["priesthood","courage","covenant","kingship","leadership"]),

 B(slug="josiah", name="Josiah", era="Divided Kingdom", charge="A tender heart at the reading of the book; turning to the Lord with all his heart, soul, and might, according to all the law of Moses",
  summary="Eight years old when crowned, sixteen when he began to seek the God of David, twenty when he began to purge Judah, twenty-six when the book of the law was found in the house and read to him. He rent his clothes, gathered the people, read it to them himself, and kept a passover like none since Samuel. He was promised he would be gathered to his grave in peace before the evil came. His death at Megiddo is its own case.",
  offense="When the king had heard the words of the book of the law, he rent his clothes. He read in their ears all the words of the book of the covenant, and the king stood by a pillar, and made a covenant before the Lord, to walk after the Lord, and to keep his commandments and his testimonies and his statutes with all their heart and all their soul. He put down the idolatrous priests; he brake down the houses of the sodomites; he defiled Topheth, that no man might make his son or his daughter to pass through the fire to Molech; he brake in pieces the images, and cut down the groves. Surely there was not holden such a passover from the days of the judges.",
  judgment="Because thine heart was tender, and thou hast humbled thyself before the Lord, when thou heardest what I spake against this place, and hast rent thy clothes, and wept before me; I also have heard thee, saith the Lord. Behold therefore, I will gather thee unto thy fathers, and thou shalt be gathered into thy grave in peace; and thine eyes shall not see all the evil which I will bring upon this place. And like unto him was there no king before him, that turned to the Lord with all his heart, and with all his soul, and with all his might, according to all the law of Moses; neither after him arose there any like him. Sirach: the remembrance of Josias is like the composition of the perfume that is made by the art of the apothecary.",
  refs=[R("2 Kings",22,"8-13"),R("2 Kings",22,"18-20"),R("2 Kings",23,"1-3"),R("2 Kings",23,"4-14"),R("2 Kings",23,"21-25"),R("2 Chronicles",34,"1-7"),R("2 Chronicles",35,"1-19"),R("Sirach",49,"1-4"),R("Deuteronomy",6,"4-5")],
  laws=["2L","2F","4B","2D","9A","10H"], topics=["repentance","keep-the-commandments","idolatry","passover","study"], themes=["kingship","repentance","obedience","covenant","zeal"]),

 B(slug="the-rechabites", name="Jonadab and the Rechabites", era="Divided Kingdom", charge="Obeying the commandment of Jonadab their father for over two hundred years: no wine, no house, no vineyard, no field",
  summary="The Lord had Jeremiah set wine before a whole clan in a chamber of the temple. They refused it: their father Jonadab had commanded them to drink none, build no house and sow no seed, and they had kept it all their days. The Lord held them up against Judah, who would not obey him though he rose early and spoke, and promised Jonadab a man before him for ever.",
  offense="But they said, We will drink no wine: for Jonadab the son of Rechab our father commanded us, saying, Ye shall drink no wine, neither ye, nor your sons for ever: neither shall ye build house, nor sow seed, nor plant vineyard, nor have any: but all your days ye shall dwell in tents. Thus have we obeyed the voice of Jonadab the son of Rechab our father in all that he hath charged us. The words of Jonadab the son of Rechab, that he commanded his sons not to drink wine, are performed; for unto this day they drink none, but obey their father's commandment: notwithstanding I have spoken unto you, rising early and speaking; but ye hearkened not unto me.",
  judgment="Because ye have obeyed the commandment of Jonadab your father, and kept all his precepts, and done according unto all that he hath commanded you: therefore thus saith the Lord of hosts, the God of Israel; Jonadab the son of Rechab shall not want a man to stand before me for ever. The fifth commandment's promise, kept by a house for eight generations, and answered for ever.",
  refs=[R("Jeremiah",35,"1-11"),R("Jeremiah",35,"12-17"),R("Jeremiah",35,"18-19"),R("2 Kings",10,"15-16"),R("Exodus",20,"12"),R("Ephesians",6,"1-3")],
  laws=["6B","1A","2H","12G"], topics=["honour","obedience","training-children","drinking"], themes=["obedience","family","covenant","honour-of-parents"]),

 B(slug="ebed-melech", name="Ebed-melech the Ethiopian", era="Divided Kingdom", charge="Going to the king for Jeremiah, and drawing him up out of the dungeon with old cast clouts and rotten rags",
  summary="The princes had put Jeremiah in a dungeon of mire to die. A eunuch of the king's house, an Ethiopian, went out to Zedekiah at the gate and told him the prophet was likely to die of hunger where he was. The king gave him thirty men and he drew Jeremiah up with rags under his armholes. Before the city fell the Lord sent him his own word: thy life for a prey, because thou hast put thy trust in me.",
  offense="Ebed-melech went forth out of the king's house, and spake to the king, saying, My lord the king, these men have done evil in all that they have done to Jeremiah the prophet, whom they have cast into the dungeon; and he is like to die for hunger in the place where he is. So Ebed-melech took the men with him, and went into the house of the king under the treasury, and took thence old cast clouts and old rotten rags, and let them down by cords into the dungeon to Jeremiah. And they drew up Jeremiah with cords, and took him up out of the dungeon.",
  judgment="Go and speak to Ebed-melech the Ethiopian, saying, Thus saith the Lord of hosts, the God of Israel; Behold, I will bring my words upon this city for evil, and not for good; and they shall be accomplished in that day before thee. But I will deliver thee in that day, saith the Lord: and thou shalt not be given into the hand of the men of whom thou art afraid. For I will surely deliver thee, and thou shalt not fall by the sword, but thy life shall be for a prey unto thee: because thou hast put thy trust in me, saith the Lord.",
  refs=[R("Jeremiah",38,"4-6"),R("Jeremiah",38,"7-13"),R("Jeremiah",39,"15-18"),R("Proverbs",24,"11-12"),R("Matthew",25,"35-36"),R("Isaiah",56,"3-5")],
  laws=["3K","15B","2B","4F"], topics=["deliverance","trust-god","strangers","poor"], themes=["courage","mercy","deliverance","faith"]),

 # ---------------- Exile and Return ----------------
 B(slug="daniel", name="Daniel", era="Exile and Return", charge="Purposing in his heart not to defile himself with the king's meat; praying three times a day with his windows open toward Jerusalem, decree or no decree",
  summary="A captive boy in Babylon refused the king's meat and wine and asked for pulse and water; ten days later he looked better than the rest. Sixty years later, an old man under Darius, he kept his windows open and prayed as before, knowing the den was signed. He was in the den one night and the God he served shut the lions' mouths.",
  offense="Daniel purposed in his heart that he would not defile himself with the portion of the king's meat, nor with the wine which he drank. When Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime. His enemies had already ruled out every other charge: we shall not find any occasion against this Daniel, except we find it against him concerning the law of his God.",
  judgment="God had brought Daniel into favour and tender love with the prince of the eunuchs. At the end of ten days their countenances appeared fairer and fatter in flesh than all the children which did eat the portion of the king's meat. God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams. My God hath sent his angel, and hath shut the lions' mouths, that they have not hurt me: forasmuch as before him innocency was found in me. So Daniel prospered in the reign of Darius, and in the reign of Cyrus the Persian. Ezekiel names him with Noah and Job; Gabriel calls him greatly beloved.",
  refs=[R("Daniel",1,"8-16"),R("Daniel",1,"17-21"),R("Daniel",6,"4-5"),R("Daniel",6,"10-11"),R("Daniel",6,"16-23"),R("Daniel",6,"25-28"),R("Daniel",9,"20-23"),R("Ezekiel",14,"14"),R("Leviticus",11,"46-47")],
  laws=["14A","14D","2N","2H","2C"], topics=["dietary-laws","clean-food","prayer","obedience","deliverance"], themes=["obedience","prayer","faith","deliverance","courage"]),

 B(slug="shadrach-meshach-and-abednego", name="Shadrach, Meshach, and Abednego", era="Exile and Return", charge="Refusing to fall down and worship the golden image; not careful to answer the king in this matter",
  summary="Every people, nation and language fell down at the sound of the music. Three officers of the province of Babylon stood. Told they would go into the furnace and asked who was the God that should deliver them out of the king's hands, they answered that their God was able, and that if he did not, they would still not serve Nebuchadnezzar's gods. The furnace killed the men who threw them in and did not singe their hair.",
  offense="Be it known unto thee, O king, that we will not serve thy gods, nor worship the golden image which thou hast set up. If it be so, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver us out of thine hand, O king. But if not, be it known unto thee, O king, that we will not serve thy gods. In the Song of the Three Children, Azarias prayed in the midst of the fire: we have sinned and committed iniquity; yet deliver us not up wholly, for thy name's sake.",
  judgment="Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God. Upon whose bodies the fire had no power, nor was an hair of their head singed, neither were their coats changed, nor the smell of fire had passed on them. Nebuchadnezzar spake: Blessed be the God of Shadrach, Meshach, and Abednego, who hath sent his angel, and delivered his servants that trusted in him, and have changed the king's word, and yielded their bodies, that they might not serve nor worship any god, except their own God. Then the king promoted them in the province of Babylon. The men that took them up were slain by the flame of the fire.",
  refs=[R("Daniel",3,"8-12"),R("Daniel",3,"13-18"),R("Daniel",3,"19-25"),R("Daniel",3,"26-30"),R("Song of the Three Children",1,"1-27"),R("Hebrews",11,"33-34"),R("Exodus",20,"3-5"),R("1 Maccabees",2,"59")],
  laws=["2D","1A","10F","2B"], topics=["graven-images","idolatry","believe","deliverance","fire"], themes=["faith","courage","idolatry","deliverance","martyrdom"]),

 B(slug="mordecai-and-esther", name="Mordecai and Esther", era="Exile and Return", charge="Mordecai: bowing not to Haman. Esther: going in to the king against the law, after three days' fast: if I perish, I perish",
  summary="A Jew in the king's gate would not bow to an Agagite, and the Agagite bought a decree to kill every Jew in the empire. His cousin the queen fasted three days with all the Jews of Shushan and went in to the king uncalled. Haman was hanged on his own gallows, the Jews were given the day, and Mordecai was next unto the king. The feast of Purim keeps it.",
  offense="All the king's servants bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence; for he had told them that he was a Jew. Esther: Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish. Mordecai's word to her: who knoweth whether thou art come to the kingdom for such a time as this?",
  judgment="So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king's wrath pacified. The king took off his ring, which he had taken from Haman, and gave it unto Mordecai. The Jews had light, and gladness, and joy, and honour. Mordecai the Jew was next unto king Ahasuerus, and great among the Jews, and accepted of the multitude of his brethren, seeking the wealth of his people, and speaking peace to all his seed. The Greek Esther adds Mordecai's dream and the Lord's answer: the Lord hath done wonders for his people.",
  refs=[R("Esther",3,"1-6"),R("Esther",4,"13-17"),R("Esther",5,"1-3"),R("Esther",7,"1-10"),R("Esther",8,"1-8"),R("Esther",8,"15-17"),R("Esther",9,"20-28"),R("Esther",10,"1-3"),R("Esther (Greek)",10,"4-13"),R("Exodus",17,"16")],
  laws=["2D","14E","2N","2B","11A"], topics=["idolatry","fasting","purim","deliverance","our-enemies"], themes=["faith","courage","deliverance","fasting","kingship"]),

 B(slug="ezra", name="Ezra", era="Exile and Return", charge="Preparing his heart to seek the law of the Lord, and to do it, and to teach in Israel statutes and judgments",
  summary="A ready scribe in the law of Moses came up from Babylon with the king's letter and the king's silver, refused a guard because he had told the king the hand of God is on all that seek him, fasted at the river Ahava, and arrived. He read the law to the people from morning to midday, and they wept, and kept the feast of tabernacles as it had not been kept since Joshua.",
  offense="For Ezra had prepared his heart to seek the law of the Lord, and to do it, and to teach in Israel statutes and judgments. I was ashamed to require of the king a band of soldiers and horsemen to help us against the enemy in the way: because we had spoken unto the king, saying, The hand of our God is upon all them for good that seek him. So we fasted and besought our God for this: and he was intreated of us. He read in the book in the law of God distinctly, and gave the sense, and caused them to understand the reading.",
  judgment="And the king granted him all his request, according to the hand of the Lord his God upon him. Blessed be the Lord God of our fathers, which hath put such a thing as this in the king's heart, to beautify the house of the Lord which is in Jerusalem. The hand of our God was upon us, and he delivered us from the hand of the enemy, and of such as lay in wait by the way. And all the people went their way to eat, and to drink, and to send portions, and to make great mirth, because they had understood the words that were declared unto them. Since the days of Jeshua the son of Nun unto that day had not the children of Israel done so. And there was very great gladness.",
  refs=[R("Ezra",7,"6-10"),R("Ezra",7,"27-28"),R("Ezra",8,"21-23"),R("Ezra",8,"31-32"),R("Nehemiah",8,"1-8"),R("Nehemiah",8,"9-12"),R("Nehemiah",8,"13-18"),R("1 Esdras",8,"1-8")],
  laws=["2F","4B","6D","14E","20A"], topics=["study","keep-the-commandments","fasting","feast-of-tabernacles","understanding"], themes=["obedience","teaching","fasting","feasts","provision"]),

 B(slug="nehemiah", name="Nehemiah", era="Exile and Return", charge="Building the wall in fifty-two days with a sword in one hand; taking no governor's bread; forbidding usury; shutting the gates on the Sabbath; remember me, O my God, for good",
  summary="A cupbearer wept for the walls of Jerusalem, prayed four months, asked the king, and came. He built the wall against Sanballat with half the people holding spears, made the nobles give back the usury they had taken from their brethren, refused the governor's allowance for twelve years, threw Tobiah's furniture out of the temple, chased Sanballat's son-in-law out of the priesthood, and shut the gates on the Sabbath. Four times his prayer is the same: remember me, O my God, for good.",
  offense="The former governors that had been before me were chargeable unto the people; but so did not I, because of the fear of God. I rebuked the nobles: ye exact usury, every one of his brother. Restore, I pray you, to them, even this day, their lands, their vineyards, their oliveyards, and their houses, also the hundredth part of the money. And they said, We will restore them. I commanded that the gates should be shut, and charged that they should not be opened till after the sabbath: and some of my servants set I at the gates, that there should no burden be brought in on the sabbath day. Remember me, O my God, concerning this, and wipe not out my good deeds that I have done for the house of my God.",
  judgment="And the king granted me, according to the good hand of my God upon me. So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days. And it came to pass, that when all our enemies heard thereof, and all the heathen that were about us saw these things, they were much cast down in their own eyes: for they perceived that this work was wrought of our God. Think upon me, my God, for good, according to all that I have done for this people. Sirach: among the elect was Neemias, whose renown is great, who raised up for us the walls that were fallen, and set up the gates and the bars, and raised up our ruins again.",
  refs=[R("Nehemiah",1,"4-11"),R("Nehemiah",2,"4-8"),R("Nehemiah",4,"15-23"),R("Nehemiah",5,"6-13"),R("Nehemiah",5,"14-19"),R("Nehemiah",6,"15-16"),R("Nehemiah",13,"15-22"),R("Nehemiah",13,"30-31"),R("Sirach",49,"13")],
  laws=["16C","9C","8A","15B","13A","2N"], topics=["poor","sabbath","kings-and-priests","prayer","labour"], themes=["leadership","justice","sabbath","courage","prayer"]),

 B(slug="zerubbabel-and-joshua-the-high-priest", name="Zerubbabel and Joshua the high priest", era="Exile and Return", charge="Obeying the voice of the Lord by Haggai; rising up and working on the house of the Lord",
  summary="Sixteen years the temple foundation lay bare while the people built themselves ceiled houses and said the time was not come. Haggai spoke, and the governor and the high priest with the remnant of the people obeyed and came and worked, twenty-four days after the word. The Lord said, I am with you, and by Zechariah, not by might, nor by power, but by my spirit.",
  offense="Then Zerubbabel the son of Shealtiel, and Joshua the son of Josedech, the high priest, with all the remnant of the people, obeyed the voice of the Lord their God, and the words of Haggai the prophet, as the Lord their God had sent him, and the people did fear before the Lord. And the Lord stirred up the spirit of Zerubbabel, and the spirit of Joshua, and the spirit of all the remnant of the people; and they came and did work in the house of the Lord of hosts, their God. Zechariah: Joshua stood before the angel clothed with filthy garments, and Satan at his right hand to resist him; and the Lord rebuked Satan and clothed him with change of raiment.",
  judgment="Then spake Haggai the Lord's messenger in the Lord's message unto the people, saying, I am with you, saith the Lord. From this day will I bless you. In that day, saith the Lord of hosts, will I take thee, O Zerubbabel, my servant, and will make thee as a signet: for I have chosen thee. The hands of Zerubbabel have laid the foundation of this house; his hands shall also finish it. And the elders of the Jews builded, and they prospered through the prophesying of Haggai the prophet and Zechariah, and finished it in the sixth year of Darius. Sirach names them together: Zorobabel, as a signet on the right hand; Jesus the son of Josedec, who set up the holy temple to the Lord.",
  refs=[R("Haggai",1,"1-8"),R("Haggai",1,"12-15"),R("Haggai",2,"4-9"),R("Haggai",2,"18-23"),R("Zechariah",3,"1-7"),R("Zechariah",4,"6-10"),R("Ezra",6,"14-16"),R("Sirach",49,"11-12")],
  laws=["2H","13D","20A","8A"], topics=["obedience","work","kings-and-priests","fear-god"], themes=["obedience","leadership","priesthood","covenant"]),

 # ---------------- Second Temple ----------------
 B(slug="tobit", name="Tobit", era="Second Temple (Apocrypha)", charge="Walking in truth and justice all his days; alms, tithes, and burying the dead of his people at the risk of his own life",
  summary="A captive of Naphtali in Nineveh, he went alone to Jerusalem for the feasts when all his tribe went to Dan's calf, gave the double tithe, fed the hungry, clothed the naked, and buried the men Sennacherib killed even after it cost him everything he owned. He was blinded by sparrows' dung and prayed to die. The angel Raphael was sent, his son came home with a wife and the money, and his eyes were opened.",
  offense="I Tobit have walked all the days of my life in the ways of truth and justice. I alone went often to Jerusalem at the feasts, as it was ordained unto all the people of Israel by an everlasting decree, having the firstfruits and tenths of increase, with that which was first shorn; and them gave I at the altar to the priests. I gave many alms to my brethren, and gave my bread to the hungry, and my clothes to the naked: and if I saw any of my nation dead, or cast about the walls of Nineve, I buried him. Alms doth deliver from death, and suffereth not to come into darkness.",
  judgment="Raphael: When thou didst pray, and Sara thy daughter in law, I did bring the remembrance of your prayers before the Holy One: and when thou didst bury the dead, I was with thee likewise. I am Raphael, one of the seven holy angels, which present the prayers of the saints, and which go in and out before the glory of the Holy One. The whiteness pilled away from the corners of his eyes: and when he saw his son, he fell upon his neck. He was an hundred and eight and fifty years old, and buried honourably; and before he died he saw Nineveh destroyed as Jonas had said, and rejoiced.",
  refs=[R("Tobit",1,"3-8"),R("Tobit",1,"16-20"),R("Tobit",2,"1-10"),R("Tobit",4,"5-11"),R("Tobit",11,"7-15"),R("Tobit",12,"6-15"),R("Tobit",14,"1-2"),R("Tobit",14,"11-15"),R("Deuteronomy",14,"22-29")],
  laws=["20E","15A","15E","9A","3A"], topics=["giving","alms-deliver","tithes-for-levi","appear-3-times","poor"], themes=["mercy","faith","obedience","provision","healing"]),

 B(slug="judith", name="Judith", era="Second Temple (Apocrypha)", charge="A widow who feared God greatly, fasting all the days of her widowhood; going out to Holofernes in the name of the Lord",
  summary="When Bethulia's elders promised to surrender in five days if God did not help, a widow who had fasted since her husband died told them they were tempting the Lord. She prayed, put off her sackcloth, went out to the Assyrian camp with her maid, ate only her own clean food, and came back with the head of Holofernes in a bag. Israel praised her, she gave the spoil to the temple, and no one made the Israelites afraid in her days.",
  offense="She was a widow three years and four months; she fasted all the days of her widowhood, save the eves of the sabbaths and the sabbaths, and the eves of the new moons and the new moons. She feared God greatly, and there was none that gave her an ill word. To the elders: who are ye, that have tempted God this day, and stand instead of God among the children of men? In the camp she would not eat the meat of Holofernes, but ate of her own that she had prepared, and went out every night to the valley to pray. Then she took his sword, and she smote twice upon his neck with all her might, and she took away his head from him.",
  judgment="Blessed art thou of the most high God above all the women upon the earth: and blessed be the Lord God, which hath created the heavens and the earth, which hath directed thee to the cutting off of the head of the chief of our enemies. Thou art the exaltation of Jerusalem, thou art the great glory of Israel, thou art the great rejoicing of our nation. Judith dedicated all the stuff of Holofernes unto the Lord. And there was none that made the children of Israel any more afraid in the days of Judith, nor a long time after her death.",
  refs=[R("Judith",8,"4-8"),R("Judith",8,"11-17"),R("Judith",9,"1-14"),R("Judith",12,"1-9"),R("Judith",13,"4-10"),R("Judith",13,"17-20"),R("Judith",15,"8-10"),R("Judith",16,"18-25")],
  laws=["14E","2C","14A","22A","2N"], topics=["fasting","fear-god","clean-food","our-enemies","prayer"], themes=["faith","courage","fasting","deliverance","war"]),

 B(slug="susanna", name="Susanna", era="Second Temple (Apocrypha)", charge="Choosing to fall into the hands of the elders rather than sin in the sight of the Lord",
  summary="Two elders and judges of the people caught her alone in her husband's garden and gave her a choice: consent, or be accused of adultery and put to death. She cried out. They testified, the assembly condemned her, and she cried to the Lord on the way to die. Daniel, a young man, separated the witnesses and caught them in a lie about a tree. They died by the law of Moses for false witness, and the innocent blood was saved.",
  offense="Susanna sighed, and said, I am straitened on every side: for if I do this thing, it is death unto me: and if I do it not I cannot escape your hands. It is better for me to fall into your hands, and not do it, than to sin in the sight of the Lord. With that Susanna cried with a loud voice. Condemned, she cried out with a loud voice, and said, O everlasting God, that knowest the secrets, and knowest all things before they be: thou knowest that they have borne false witness against me, and, behold, I must die; whereas I never did such things as these men have maliciously invented against me.",
  judgment="And the Lord heard her voice. Therefore when she was led to be put to death, the Lord raised up the holy spirit of a young youth whose name was Daniel. Under what tree sawest thou them? Under a mastick tree. Under an holm tree. With that all the assembly cried out with a loud voice, and praised God, who saveth them that trust in him. And according to the law of Moses they did unto them in such sort as they maliciously intended to do to their neighbour: and they put them to death. Thus the innocent blood was saved the same day. Therefore Chelcias and his wife praised God for their daughter Susanna, because there was no dishonesty found in her.",
  refs=[R("Susanna",1,"1-4"),R("Susanna",1,"19-27"),R("Susanna",1,"42-46"),R("Susanna",1,"47-59"),R("Susanna",1,"60-64"),R("Deuteronomy",19,"16-19"),R("Genesis",39,"9")],
  laws=["5D","12A","4E","2N"], topics=["adultery","witnesses","prayer","deliverance"], themes=["chastity","faith","false-witness","deliverance","justice"]),

 B(slug="eleazar-the-scribe", name="Eleazar the scribe", era="Second Temple (Apocrypha)", charge="Choosing to die gloriously rather than eat swine's flesh, or pretend to, at ninety years old",
  summary="One of the principal scribes, an aged man and of a well favoured countenance, was compelled to open his mouth and eat swine's flesh. He spat it out. Old friends offered to let him bring his own meat and only pretend. He refused, so that the young would not be deceived by Eleazar, being fourscore years old and ten, into thinking he had gone over to a strange religion. He went to the torment and died leaving his death for an example.",
  offense="But he choosing rather to die gloriously, than to live stained with such an abomination, spit it forth, and came of his own accord to the torment. Being fourscore years old and ten: it becometh not our age in any wise to dissemble, whereby many young persons might think that Eleazar was now gone to a strange religion. For though for the present time I should be delivered from the punishment of men: yet should I not escape the hand of the Almighty, neither alive, nor dead. Wherefore now, manfully changing this life, I will shew myself such an one as mine age requireth, and leave a notable example to such as be young to die willingly and courageously for the honourable and holy laws.",
  judgment="And thus this man died, leaving his death for an example of a noble courage, and a memorial of virtue, not only unto young men, but unto all his nation. When he was ready to die with stripes, he groaned, and said, It is manifest unto the Lord, that hath the holy knowledge, that whereas I might have been delivered from death, I now endure sore pains in body by being beaten: but in soul am well content to suffer these things, because I fear him. The blessing recorded is the memorial: his name and his refusal, kept by his nation for ever, and the resurrection the next chapter's martyrs claim aloud.",
  refs=[R("2 Maccabees",6,"18-20"),R("2 Maccabees",6,"21-28"),R("2 Maccabees",6,"29-31"),R("Leviticus",11,"7-8"),R("Deuteronomy",14,"8"),R("Hebrews",11,"35-38")],
  laws=["14B","14D","2C","12A"], topics=["dietary-laws","clean-food","fear-god","suffering"], themes=["martyrdom","faith","courage","obedience"]),

 B(slug="the-seven-brethren-and-their-mother", name="The seven brethren and their mother", era="Second Temple (Apocrypha)", charge="Refusing to taste swine's flesh under torture, seven times over, in hope of the resurrection",
  summary="Seven brothers and their mother were taken and compelled by the king to taste swine's flesh, and tormented with scourges and whips when they would not. One after another they were flayed, dismembered and fried, each speaking the law and the resurrection to the king before he died. The mother watched all seven and exhorted them in her own language, and died last. Their hope is written plainly: the King of the world shall raise us up, who have died for his laws, unto everlasting life.",
  offense="We are ready to die, rather than to transgress the laws of our fathers. Thou like a fury takest us out of this present life, but the King of the world shall raise us up, who have died for his laws, unto everlasting life. The mother: I cannot tell how ye came into my womb; the Creator of the world, who formed the generation of man, will also of his own mercy give you breath and life again, as ye now regard not your own selves for his laws' sake. To the youngest: fear not this tormentor, but, being worthy of thy brethren, take thy death, that I may receive thee again in mercy with thy brethren.",
  judgment="The blessing they claimed is the one the law's own words hold out: everlasting life, and to be received again with their brethren. The seventh: our brethren, who now have suffered a short pain, are dead under God's covenant of everlasting life. The chronicler: let this be enough now to have spoken concerning the idolatrous feasts, and the extreme tortures. Hebrews remembers them without naming them: others were tortured, not accepting deliverance; that they might obtain a better resurrection. Antiochus' own end is his own case, and it followed within the year.",
  refs=[R("2 Maccabees",7,"1-6"),R("2 Maccabees",7,"7-19"),R("2 Maccabees",7,"20-29"),R("2 Maccabees",7,"30-42"),R("Hebrews",11,"35-38"),R("Daniel",12,"2-3"),R("Matthew",10,"28")],
  laws=["14B","2C","2F","6B"], topics=["dietary-laws","fear-god","suffering","keep-the-commandments","mothers-day"], themes=["martyrdom","faith","courage","family","resurrection"]),

 B(slug="mattathias", name="Mattathias", era="Second Temple (Apocrypha)", charge="Zealous for the law: refusing the king's commandment at Modin, and executing the apostate on the altar as Phinehas did Zambri",
  summary="The king's officers came to Modin to make the people sacrifice, and offered Mattathias the priest wealth and the king's friendship to go first. He answered that though every nation obeyed, he and his sons would walk in the covenant of their fathers. When a Jew came forward to sacrifice, Mattathias killed him on the altar, killed the king's commissioner, pulled the altar down, and fled to the mountains with his sons. The Maccabean deliverance began there.",
  offense="Though all the nations that are under the king's dominion obey him, and fall away every one from the religion of their fathers, and give consent to his commandments: yet will I and my sons and my brethren walk in the covenant of our fathers. God forbid that we should forsake the law and the ordinances. We will not hearken to the king's words, to go from our religion, either on the right hand, or the left. He ran and slew the Jew upon the altar, and killed the king's commissioner, and the altar he pulled down. Thus dealt he zealously for the law of God, like as Phinees did unto Zambri the son of Salom. And Mattathias cried throughout the city with a loud voice, saying, Whosoever is zealous of the law, and maintaineth the covenant, let him follow me.",
  judgment="His deathbed roll of the fathers is the blessing he claimed: Phinees our father in being zealous and fervent obtained the covenant of an everlasting priesthood. Daniel for his innocency was delivered from the mouth of lions. And thus consider ye, throughout all ages, that none that put their trust in him shall be overcome. He blessed his sons and was gathered to his fathers, and all Israel made great lamentation for him. Judas and Simon after him took the city and the temple back, and the feast of the dedication is kept to this day.",
  refs=[R("1 Maccabees",2,"15-22"),R("1 Maccabees",2,"23-28"),R("1 Maccabees",2,"29-41"),R("1 Maccabees",2,"49-64"),R("1 Maccabees",2,"65-70"),R("Numbers",25,"7-13"),R("Deuteronomy",13,"6-11")],
  laws=["2D","2F","10F","20B","22A"], topics=["idolatry","keep-the-commandments","peer-pressure","kings-and-priests","compromise"], themes=["zeal","courage","covenant","priesthood","war"]),

 B(slug="judas-maccabeus", name="Judas Maccabeus", era="Second Temple (Apocrypha)", charge="Going to battle with prayer and the law, keeping the ordinances of war, and cleansing the sanctuary",
  summary="Mattathias' third son gathered those that kept the law, sent home the fearful and the newly married as Deuteronomy commands, prayed before every battle, and beat Apollonius, Seron, Gorgias, Lysias and Nicanor with a fraction of their numbers. He cleansed the sanctuary on the twenty-fifth of Chislev, three years to the day from its defiling, and ordained the eight days of Dedication. His prayer for the dead after Adullam is the plainest hope of resurrection in the Old Testament.",
  offense="It is no hard matter for many to be shut up in the hands of a few; and with the God of heaven it is all one, to deliver with a great multitude, or a small company: for the victory of battle standeth not in the multitude of an host; but strength cometh from heaven. He commanded, according to the law, those who were building houses, or had betrothed wives, or were planting vineyards, or were fearful, to return home. He gave the army the watchword, The help of God. And Judas and his brethren said, Behold, our enemies are discomfited: let us go up to cleanse and dedicate the sanctuary. He made a reconciliation for the dead, that they might be delivered from sin.",
  judgment="So Judas fell upon them, and they fled; and the fame of him was spread abroad even to the utmost part of the earth. They built the sanctuary anew and offered sacrifice according to the law upon the new altar of burnt offerings; and there was very great gladness among the people, for that the reproach of the heathen was put away. Judas and his brethren with the whole congregation of Israel ordained, that the days of the dedication of the altar should be kept in their season from year to year by the space of eight days. Onias and Jeremiah appeared to him in a dream, and Jeremiah gave him a sword of gold: take this holy sword, a gift from God, with the which thou shalt wound the adversaries.",
  refs=[R("1 Maccabees",3,"18-22"),R("1 Maccabees",3,"55-60"),R("1 Maccabees",4,"36-59"),R("2 Maccabees",8,"16-24"),R("2 Maccabees",12,"38-45"),R("2 Maccabees",15,"11-16"),R("2 Maccabees",15,"25-29"),R("Deuteronomy",20,"5-9"),R("John",10,"22")],
  laws=["22A","22C","22F","2N","9A"], topics=["army","feast-of-dedication","prayer","our-enemies","destruction-of-nicanor"], themes=["war","faith","prayer","zeal","feasts","deliverance"]),

 B(slug="onias-the-high-priest", name="Onias the high priest", era="Second Temple (Apocrypha)", charge="Godliness and hatred of wickedness, so that the laws were kept very well and the city lived in peace",
  summary="While Onias was high priest the holy city was inhabited with all peace and the laws kept very well, and even the kings of the nations sent gifts to the temple. When Heliodorus came to rob the treasury, Onias' prayer and the priests' brought the horse and the two young men that scourged him, and Onias' sacrifice restored him. He was murdered afterward under a sworn peace; Judas saw him after death, praying for the people.",
  offense="Because of the godliness of Onias the high priest, and his hatred of wickedness, the holy city was inhabited with all peace, and the laws were kept very well. When Simon slandered him, he went to the king, not to be an accuser of his countrymen, but seeking the good of all, both publick and private; for he saw that it was impossible that the state should continue quiet, without the king's providence. When the king's messenger was struck down in the treasury, the high priest, fearing lest the king should misconceive that some treachery had been done to Heliodorus by the Jews, offered a sacrifice for the health of the man.",
  judgment="Then the high priest offered sacrifice for the health of the man; and the Lord restored Heliodorus to life. Heliodorus testified to all men the works of the great God, which he had seen with his eyes. After his murder, Judas saw in a dream Onias, who had been high priest, a virtuous and a good man, reverend in conversation, gentle in condition, well spoken also, and exercised from a child in all points of virtue, holding up his hands and praying for the whole body of the Jews. The blessing recorded is a city at peace under the law, a martyr's honour, and a place among those who pray for the people.",
  refs=[R("2 Maccabees",3,"1-3"),R("2 Maccabees",3,"31-35"),R("2 Maccabees",4,"1-6"),R("2 Maccabees",4,"33-38"),R("2 Maccabees",15,"12-14"),R("Sirach",50,"1-4")],
  laws=["20A","20B","4B","2N"], topics=["kings-and-priests","prayer","peace","persecution"], themes=["priesthood","peace","prayer","martyrdom","leadership"]),

 # ---------------- Gospels ----------------
 B(slug="zacharias-and-elisabeth", name="Zacharias and Elisabeth", era="Gospels", charge="Both righteous before God, walking in all the commandments and ordinances of the Lord blameless",
  summary="A priest of the course of Abia and a daughter of Aaron, old, childless, and blameless in the whole law. Their prayer was heard at the altar of incense: a son, to be called John, filled with the Holy Ghost from his mother's womb, who would go before the Lord in the spirit and power of Elias. Zacharias' unbelief at the news is its own case; the blessing stood.",
  offense="They were both righteous before God, walking in all the commandments and ordinances of the Lord blameless. He executed the priest's office before God in the order of his course, according to the custom of the priest's office. Elisabeth hid herself five months, saying, Thus hath the Lord dealt with me in the days wherein he looked on me, to take away my reproach among men. On the eighth day they circumcised the child, and against all their kindred named him as the angel had said.",
  judgment="Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John. And thou shalt have joy and gladness; and many shall rejoice at his birth. For he shall be great in the sight of the Lord. Her neighbours and her cousins heard how the Lord had shewed great mercy upon her; and they rejoiced with her. Zacharias was filled with the Holy Ghost and prophesied: and thou, child, shalt be called the prophet of the Highest. Christ's own verdict on their son: among them that are born of women there hath not risen a greater than John the Baptist.",
  refs=[R("Luke",1,"5-7"),R("Luke",1,"8-17"),R("Luke",1,"24-25"),R("Luke",1,"57-66"),R("Luke",1,"67-80"),R("Matthew",11,"11"),R("Psalms",113,"9")],
  laws=["2F","20B","2N","6B"], topics=["keep-the-commandments","kings-and-priests","prayer","circumcision"], themes=["obedience","prayer","priesthood","family","provision"]),

 B(slug="joseph-the-husband-of-mary", name="Joseph, the husband of Mary", era="Gospels", charge="A just man; doing as the angel of the Lord bade him, four times, without a word recorded",
  summary="Betrothed to a woman found with child, and a just man, he meant to put her away privily rather than make her a public example. An angel told him in a dream whose the child was and he took her, and knew her not till she had brought forth. He was told to flee to Egypt and went by night; told to return, and returned; warned, and turned aside to Galilee. Scripture records no word he spoke, only what he did.",
  offense="Joseph her husband, being a just man, and not willing to make her a publick example, was minded to put her away privily. Then Joseph being raised from sleep did as the angel of the Lord had bidden him, and took unto him his wife. When he arose, he took the young child and his mother by night, and departed into Egypt. Every year his parents went to Jerusalem at the feast of the passover. And he did all things according to the law of the Lord: the circumcision on the eighth day, the presentation, the pair of turtledoves.",
  judgment="Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost. And she shall bring forth a son, and thou shalt call his name Jesus: for he shall save his people from their sins. The blessing on him is the charge itself: the Son of God was subject unto him, and grew up under his roof in Nazareth, and was called the carpenter's son. Arise, and take the young child and his mother, and go into the land of Israel: for they are dead which sought the young child's life.",
  refs=[R("Matthew",1,"18-25"),R("Matthew",2,"13-15"),R("Matthew",2,"19-23"),R("Luke",2,"21-24"),R("Luke",2,"39-41"),R("Luke",2,"51-52"),R("Deuteronomy",24,"1")],
  laws=["5B","6A","2H","9A"], topics=["obedience","marriage","family-order","men-must-lead"], themes=["obedience","family","faith","justice"]),

 B(slug="mary-the-mother-of-jesus", name="Mary, the mother of Jesus", era="Gospels", charge="Be it unto me according to thy word; blessed is she that believed",
  summary="A virgin of Nazareth, espoused, was told she would conceive by the Holy Ghost and bear the Son of the Highest, and that with God nothing shall be impossible. She answered, Behold the handmaid of the Lord; be it unto me according to thy word. Elisabeth's word to her is the verdict: blessed is she that believed. Her own song says all generations shall call her blessed, and they have.",
  offense="And Mary said, Behold the handmaid of the Lord; be it unto me according to thy word. She arose in those days and went into the hill country with haste to Elisabeth. She kept all these things, and pondered them in her heart. When the days of her purification according to the law of Moses were accomplished, they brought him to Jerusalem, to present him to the Lord; as it is written in the law of the Lord. At Cana her word to the servants was the rule she lived by: Whatsoever he saith unto you, do it. She stood by the cross.",
  judgment="Hail, thou that art highly favoured, the Lord is with thee: blessed art thou among women. Blessed art thou among women, and blessed is the fruit of thy womb. And blessed is she that believed: for there shall be a performance of those things which were told her from the Lord. My soul doth magnify the Lord, and my spirit hath rejoiced in God my Saviour. For he hath regarded the low estate of his handmaiden: for, behold, from henceforth all generations shall call me blessed. From the cross her Son gave her to the disciple he loved, and from that hour that disciple took her unto his own home.",
  refs=[R("Luke",1,"26-38"),R("Luke",1,"39-45"),R("Luke",1,"46-55"),R("Luke",2,"19"),R("Luke",2,"22-24"),R("John",2,"1-5"),R("John",19,"25-27"),R("Isaiah",7,"14")],
  laws=["2B","2H","12A","9B"], topics=["believe","obedience","the-woman","immaculate-conception"], themes=["faith","obedience","family","humility"]),

 B(slug="simeon-and-anna", name="Simeon and Anna", era="Gospels", charge="Just and devout, waiting for the consolation of Israel; a widow who departed not from the temple, serving God with fastings and prayers night and day",
  summary="An old man had been told by the Holy Ghost that he would not see death before he had seen the Lord's Christ. He came by the Spirit into the temple the day a poor couple brought a forty-day-old child with a pair of turtledoves, took him in his arms, and asked to be let go in peace. A prophetess of eighty-four who had lived in the temple since her husband died came in that same hour and spoke of him to all that looked for redemption.",
  offense="Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him. He came by the Spirit into the temple. Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity; and she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day.",
  judgment="It was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord's Christ. Then took he him up in his arms, and blessed God, and said, Lord, now lettest thou thy servant depart in peace, according to thy word: for mine eyes have seen thy salvation, which thou hast prepared before the face of all people; a light to lighten the Gentiles, and the glory of thy people Israel. And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem. Two who kept the law past the end of their strength were the first in the temple to know whom they had been waiting for.",
  refs=[R("Luke",2,"25-32"),R("Luke",2,"33-35"),R("Luke",2,"36-38"),R("Isaiah",40,"1"),R("Isaiah",49,"6"),R("Malachi",3,"1")],
  laws=["2N","14E","2B","15C"], topics=["prayer","fasting","devout","christ"], themes=["faith","prayer","fasting","patience"]),

 B(slug="the-centurion-of-capernaum", name="The centurion of Capernaum", era="Gospels", charge="Loving the nation and building the synagogue; not counting himself worthy that the Lord should come under his roof: speak the word only",
  summary="A Roman officer whose servant was dying sent the elders of the Jews, who pleaded that he was worthy, for he loved their nation and had built them a synagogue. He himself sent to say he was not worthy, and that a word would do, since he too was a man under authority. Christ marvelled, said he had not found so great faith in Israel, and the servant was healed in that hour.",
  offense="Lord, I am not worthy that thou shouldest come under my roof: but speak the word only, and my servant shall be healed. For I am a man under authority, having soldiers under me: and I say to this man, Go, and he goeth. The elders of the Jews besought him instantly, saying, That he was worthy for whom he should do this: for he loveth our nation, and he hath built us a synagogue. A Gentile who had done good to Israel and did not presume upon it.",
  judgment="When Jesus heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Israel. And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven. Go thy way; and as thou hast believed, so be it done unto thee. And his servant was healed in the selfsame hour.",
  refs=[R("Matthew",8,"5-13"),R("Luke",7,"1-10"),R("Genesis",12,"3"),R("Isaiah",56,"6-7")],
  laws=["2B","11B","17I","21A"], topics=["believe","strangers","humility","our-servants"], themes=["faith","humility","healing","hospitality"]),

 B(slug="the-woman-with-the-issue-of-blood", name="The woman with the issue of blood", era="Gospels", charge="Believing that if she might but touch his clothes she should be whole",
  summary="Twelve years unclean under the law, spent to her last penny on physicians and worse for it, she came behind him in the press and touched the border of his garment. The flow dried up in the same hour. He turned and made her say it before everyone, and gave her the verdict in front of them: thy faith hath made thee whole.",
  offense="A certain woman, which had an issue of blood twelve years, and had suffered many things of many physicians, and had spent all that she had, and was nothing bettered, but rather grew worse, when she had heard of Jesus, came in the press behind, and touched his garment. For she said, If I may touch but his clothes, I shall be whole. When she saw that she was not hid, she came trembling, and falling down before him, she declared unto him before all the people for what cause she had touched him.",
  judgment="And straightway the fountain of her blood was dried up; and she felt in her body that she was healed of that plague. And he said unto her, Daughter, be of good comfort: thy faith hath made thee whole; go in peace, and be whole of thy plague. Under the law her touch should have made him unclean; instead his made her clean, and she went home with the word that did it.",
  refs=[R("Mark",5,"25-34"),R("Luke",8,"43-48"),R("Matthew",9,"20-22"),R("Leviticus",15,"25-27"),R("Malachi",4,"2")],
  laws=["2B","14G","2C"], topics=["believe","healing","sickness","fringes"], themes=["faith","healing","humility"]),

 B(slug="the-samaritan-leper", name="The Samaritan leper who returned", era="Gospels", charge="One of ten: turning back to glorify God with a loud voice, and giving thanks at his feet",
  summary="Ten lepers stood afar off and cried for mercy, and were sent to shew themselves to the priests as the law commands. As they went they were cleansed. Nine kept going. One, a Samaritan, turned back, fell on his face at his feet and gave thanks. He alone was told, thy faith hath made thee whole.",
  offense="And one of them, when he saw that he was healed, turned back, and with a loud voice glorified God, and fell down on his face at his feet, giving him thanks: and he was a Samaritan. The other nine had obeyed the letter, going to the priests; this one came back to the one who had sent them.",
  judgment="And Jesus answering said, Were there not ten cleansed? but where are the nine? There are not found that returned to give glory to God, save this stranger. And he said unto him, Arise, go thy way: thy faith hath made thee whole. Ten were cleansed of leprosy; one went home whole.",
  refs=[R("Luke",17,"11-14"),R("Luke",17,"15-19"),R("Leviticus",14,"2-4"),R("Psalms",50,"23"),R("Psalms",103,"1-3")],
  laws=["2O","2M","14G","2B"], topics=["believe","healing","strangers"], themes=["gratitude","faith","healing"]),

 B(slug="the-widow-and-her-two-mites", name="The widow and her two mites", era="Gospels", charge="Casting in all that she had, even all her living",
  summary="He sat over against the treasury and watched the rich cast in much. A poor widow threw in two mites, which make a farthing. He called his disciples to see it, and weighed it against everything else in the box: she had cast in more than they all.",
  offense="And there came a certain poor widow, and she threw in two mites, which make a farthing. The rich cast in of their abundance; she of her want did cast in all that she had, even all her living. No one had asked her for it.",
  judgment="And he called unto him his disciples, and saith unto them, Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury: for all they did cast in of their abundance; but she of her want did cast in all that she had, even all her living. Her gift is the standard by which every other gift in the temple that day was found smaller, and it is read in every generation since.",
  refs=[R("Mark",12,"41-44"),R("Luke",21,"1-4"),R("2 Corinthians",8,"12"),R("Deuteronomy",16,"17"),R("Tobit",4,"8")],
  laws=["20E","15A","2B"], topics=["giving","poor","trust-god"], themes=["faith","giving","provision"]),

 B(slug="mary-of-bethany", name="Mary of Bethany", era="Gospels", charge="Sitting at his feet to hear his word; anointing his body aforehand to the burying",
  summary="While her sister served, she sat at his feet and heard, and he called it the good part that would not be taken from her. Six days before the passover she broke an alabaster box of spikenard, very precious, over his head and feet and wiped them with her hair. The disciples called it waste. He called it a memorial for the whole world.",
  offense="Mary sat at Jesus' feet, and heard his word. Then took Mary a pound of ointment of spikenard, very costly, and anointed the feet of Jesus, and wiped his feet with her hair: and the house was filled with the odour of the ointment. Some had indignation: why was this waste of the ointment made? for it might have been sold for more than three hundred pence, and given to the poor.",
  judgment="Mary hath chosen that good part, which shall not be taken away from her. Let her alone; why trouble ye her? she hath wrought a good work on me. She hath done what she could: she is come aforehand to anoint my body to the burying. Verily I say unto you, Wheresoever this gospel shall be preached throughout the whole world, this also that she hath done shall be spoken of for a memorial of her.",
  refs=[R("Luke",10,"38-42"),R("John",12,"1-8"),R("Mark",14,"3-9"),R("Matthew",26,"6-13"),R("Deuteronomy",6,"5")],
  laws=["2E","2J","2M","13D"], topics=["love","the-word","giving","meditate"], themes=["faith","love","giving","devotion"]),

 # ---------------- Apostolic ----------------
 B(slug="stephen", name="Stephen", era="Apostolic", charge="Full of faith and of the Holy Ghost; a face like an angel before the council; forgiving those who stoned him",
  summary="One of the seven chosen to serve tables, full of faith and power, he did great wonders and out-argued every synagogue that tried him. Accused by suborned witnesses, he preached Abraham to Solomon to a council that stopped their ears and stoned him. He saw heaven opened and the Son of man standing, and asked that the sin not be laid to their charge. A young man named Saul held the coats.",
  offense="Stephen, a man full of faith and of the Holy Ghost. And they were not able to resist the wisdom and the spirit by which he spake. All that sat in the council, looking stedfastly on him, saw his face as it had been the face of an angel. He, being full of the Holy Ghost, looked up stedfastly into heaven, and saw the glory of God, and Jesus standing on the right hand of God. And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit. And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge.",
  judgment="Behold, I see the heavens opened, and the Son of man standing on the right hand of God. The Lord had said, whosoever shall confess me before men, him shall the Son of man also confess before the angels of God; Stephen saw him stand to do it. Devout men carried Stephen to his burial, and made great lamentation over him. The blessing recorded is a witness received in heaven in sight of the witness himself, and the persecution that scattered the church to preach the word everywhere, and the coat-holder who became Paul.",
  refs=[R("Acts",6,"5-10"),R("Acts",6,"15"),R("Acts",7,"54-60"),R("Acts",8,"1-4"),R("Acts",22,"20"),R("Luke",12,"8"),R("Matthew",5,"10-12")],
  laws=["2B","3B","20A","4E"], topics=["believe","forgiveness","persecution","witnesses"], themes=["martyrdom","faith","forgiveness","courage"]),

 B(slug="barnabas", name="Barnabas", era="Apostolic", charge="Selling his land and laying the money at the apostles' feet; a good man, full of the Holy Ghost and of faith",
  summary="A Levite of Cyprus sold his land and brought the whole price to the apostles, in the same chapter and by the same rule that Ananias and Sapphira broke with theirs. He took Saul in when the disciples were afraid of him, went to find him in Tarsus when Antioch needed a teacher, and was the man Antioch's Gentiles first believed under. The apostles named him: the son of consolation.",
  offense="Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus, having land, sold it, and brought the money, and laid it at the apostles' feet. But Barnabas took Saul, and brought him to the apostles. When he came to Antioch, and had seen the grace of God, he was glad, and exhorted them all, that with purpose of heart they would cleave unto the Lord. For he was a good man, and full of the Holy Ghost and of faith.",
  judgment="And much people was added unto the Lord. The Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them. The Spirit's own naming of him for the first mission to the Gentiles is the blessing; the church's naming of him is the other: son of consolation. His gift and Ananias' lie stand a few verses apart so no one can miss the difference.",
  refs=[R("Acts",4,"34-37"),R("Acts",9,"26-27"),R("Acts",11,"22-26"),R("Acts",13,"1-3"),R("Acts",15,"25-26"),R("Deuteronomy",15,"7-8")],
  laws=["15A","15E","3A","20D"], topics=["giving","fellowship","poor","brotherly-love"], themes=["giving","faith","leadership","hospitality"]),

 B(slug="dorcas", name="Dorcas (Tabitha)", era="Apostolic", charge="Full of good works and almsdeeds which she did; the coats and garments she made for the widows",
  summary="A disciple at Joppa who clothed the widows died, and they washed her and laid her in an upper chamber and sent two men for Peter. When he came, the widows stood by him weeping and showing the coats and garments she had made. He put them out, kneeled, prayed, and said, Tabitha, arise. She opened her eyes, and he presented her alive.",
  offense="Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did. All the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them. Her works were her witnesses, and they were held up in the room where she lay.",
  judgment="Peter kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up. And he gave her his hand, and lifted her up, and when he had called the saints and widows, presented her alive. And it was known throughout all Joppa; and many believed in the Lord. The one woman raised from the dead in the Acts is the one whose alms were in every widow's hands.",
  refs=[R("Acts",9,"36-39"),R("Acts",9,"40-42"),R("Deuteronomy",24,"19-21"),R("James",1,"27"),R("Isaiah",58,"7-8"),R("Tobit",12,"8-9")],
  laws=["15C","15A","15E","13A"], topics=["giving","poor","alms-deliver","work"], themes=["mercy","giving","healing","resurrection"]),

 B(slug="cornelius", name="Cornelius", era="Apostolic", charge="A devout man, one that feared God with all his house, which gave much alms to the people, and prayed to God alway",
  summary="A centurion of the Italian band at Caesarea, a Gentile, was praying at the ninth hour when an angel told him his prayers and alms were come up for a memorial before God, and to send for Peter. Peter came, learned on the way that God is no respecter of persons, preached, and the Holy Ghost fell on the whole house before he had finished. They were the first Gentiles baptized.",
  offense="A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway. Cornelius said, Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house. When Peter came, Cornelius met him and fell down at his feet; Peter took him up: I myself also am a man. Now therefore are we all here present before God, to hear all things that are commanded thee of God.",
  judgment="Thy prayers and thine alms are come up for a memorial before God. Of a truth I perceive that God is no respecter of persons: but in every nation he that feareth him, and worketh righteousness, is accepted with him. While Peter yet spake these words, the Holy Ghost fell on all them which heard the word. And they of the circumcision which believed were astonished, as many as came with Peter, because that on the Gentiles also was poured out the gift of the Holy Ghost. And he commanded them to be baptized in the name of the Lord.",
  refs=[R("Acts",10,"1-8"),R("Acts",10,"24-33"),R("Acts",10,"34-35"),R("Acts",10,"44-48"),R("Acts",11,"13-18"),R("Tobit",12,"12"),R("Psalms",141,"2")],
  laws=["2C","15A","2N","14E"], topics=["fear-god","giving","prayer","strangers","real-gentiles"], themes=["faith","prayer","giving","hospitality","covenant"]),

 B(slug="lydia", name="Lydia", era="Apostolic", charge="A seller of purple who worshipped God; whose heart the Lord opened; who constrained the apostles to abide in her house",
  summary="Paul crossed into Europe on a vision and found no synagogue at Philippi, only women at prayer by the river. One of them, a merchant of Thyatira, heard, believed, was baptized with her household, and would not let the apostles lodge anywhere else. Her house became the church at Philippi, and after the prison and the earthquake it was where Paul and Silas went first.",
  offense="A certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us. And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us. Leaving the prison, they entered into the house of Lydia: and when they had seen the brethren, they comforted them, and departed.",
  judgment="Whose heart the Lord opened, that she attended unto the things which were spoken of Paul. The first believer in Europe recorded by name, and the first house of the church that later sent to Paul's necessity once and again, and to which he wrote that he thanked God upon every remembrance of them. The blessing on hospitality is the guests: an apostle and the gospel under her roof.",
  refs=[R("Acts",16,"11-15"),R("Acts",16,"40"),R("Philippians",1,"3-5"),R("Philippians",4,"15-16"),R("Hebrews",13,"2"),R("Romans",12,"13")],
  laws=["15A","2J","20D","3G"], topics=["strangers","fellowship","giving","baptism"], themes=["hospitality","faith","provision"]),

 B(slug="the-bereans", name="The Bereans", era="Apostolic", charge="Receiving the word with all readiness of mind, and searching the scriptures daily, whether those things were so",
  summary="Driven from Thessalonica by a mob, Paul and Silas came to Berea and found a synagogue that did two things at once: welcomed the message and checked it against the scriptures every day. Luke calls them more noble than the Thessalonians for it. Many of them believed, including honourable Greek women and men.",
  offense="These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so. They did not believe Paul because he was Paul; they believed the scriptures, and found him in them.",
  judgment="Therefore many of them believed; also of honourable women which were Greeks, and of men, not a few. When the Thessalonian Jews came to stir up the city, the brethren sent Paul away, and Silas and Timotheus abode there still. Search the scriptures, Christ had said; the Bereans are the one church named for having done it, and the church was theirs.",
  refs=[R("Acts",17,"10-12"),R("Acts",17,"13-14"),R("John",5,"39"),R("Isaiah",8,"20"),R("Psalms",119,"97-100"),R("2 Timothy",3,"14-17")],
  laws=["2F","6D","4B"], topics=["study","search-the-fathers","scripture-is-inspired","understanding"], themes=["teaching","faith","wisdom"]),

 B(slug="the-philippian-jailer", name="The Philippian jailer", era="Apostolic", charge="Believing on the Lord with all his house the same night; washing the stripes of the men he had put in the stocks",
  summary="He thrust Paul and Silas into the inner prison and made their feet fast in the stocks. At midnight they sang, the earthquake opened every door, and he drew his sword to kill himself. Paul cried out that they were all there. He fell down trembling, asked what he must do to be saved, was told, and before dawn had washed their wounds, been baptized with all his house, set meat before them, and rejoiced.",
  offense="Sirs, what must I do to be saved? And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house. And he took them the same hour of the night, and washed their stripes; and was baptized, he and all his, straightway. And when he had brought them into his house, he set meat before them.",
  judgment="And rejoiced, believing in God with all his house. The prisoners he had chained became his guests, the sword he had drawn on himself went back in its sheath, and the magistrates who had beaten Roman citizens uncondemned came the next morning to beg them to leave. The church at Philippi that Lydia opened her house to had a jailer in it.",
  refs=[R("Acts",16,"22-26"),R("Acts",16,"27-34"),R("Acts",16,"35-40"),R("Psalms",34,"18"),R("Joel",2,"32")],
  laws=["2B","15A","3K","2L"], topics=["believe","baptism","salvation","strangers"], themes=["faith","hospitality","deliverance","family"]),

 B(slug="timothy-lois-and-eunice", name="Timothy, with Lois and Eunice", era="Apostolic", charge="Unfeigned faith that dwelt first in his grandmother and his mother; knowing the holy scriptures from a child",
  summary="A boy of Lystra with a Greek father and a believing Jewish mother had been taught the scriptures from a child by two women. Paul found him well reported of, circumcised him for the Jews' sake, and took him. He became Paul's own son in the faith, the man he trusted with Ephesus, and the one he wrote his last letter to.",
  offense="When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also. From a child thou hast known the holy scriptures, which are able to make thee wise unto salvation. Timotheus was well reported of by the brethren that were at Lystra and Iconium. I have no man likeminded, who will naturally care for your state. For all seek their own, not the things which are Jesus Christ's. But ye know the proof of him, that, as a son with the father, he hath served with me in the gospel.",
  judgment="Him would Paul have to go forth with him. Timothy, my own son in the faith. This charge I commit unto thee, son Timothy, according to the prophecies which went before on thee, that thou by them mightest war a good warfare. Neglect not the gift that is in thee, which was given thee by prophecy, with the laying on of the hands of the presbytery. The blessing on the two women's teaching is the man it made: named in the address of six epistles, and left in charge of the church at Ephesus.",
  refs=[R("2 Timothy",1,"3-6"),R("2 Timothy",3,"14-17"),R("Acts",16,"1-3"),R("Philippians",2,"19-22"),R("1 Timothy",1,"2"),R("1 Timothy",1,"18"),R("1 Timothy",4,"12-16"),R("Deuteronomy",6,"6-7"),R("Proverbs",22,"6")],
  laws=["6D","6A","2F","20A"], topics=["training-children","study","mothers-day","scripture-is-inspired"], themes=["family","teaching","faith","leadership"]),

 B(slug="onesiphorus", name="Onesiphorus", era="Apostolic", charge="Oft refreshing Paul, and not ashamed of his chain; seeking him out very diligently in Rome",
  summary="When everyone in Asia had turned from Paul, one man from Ephesus went to Rome, hunted through the prisons until he found him, and kept coming. Paul's blessing on him is in the last letter he wrote: the Lord give mercy unto the house of Onesiphorus, and grant that he may find mercy of the Lord in that day.",
  offense="He oft refreshed me, and was not ashamed of my chain: but, when he was in Rome, he sought me out very diligently, and found me. And in how many things he ministered unto me at Ephesus, thou knowest very well. This thou knowest, that all they which are in Asia be turned away from me.",
  judgment="The Lord give mercy unto the house of Onesiphorus. The Lord grant unto him that he may find mercy of the Lord in that day. I was in prison, and ye came unto me: inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me. Salute the household of Onesiphorus.",
  refs=[R("2 Timothy",1,"15-18"),R("2 Timothy",4,"19"),R("Matthew",25,"36-40"),R("Hebrews",13,"3"),R("Hebrews",10,"33-34")],
  laws=["3A","15A","3K","3G"], topics=["fellowship","brotherly-love","persecution","suffering"], themes=["loyalty","mercy","hospitality","persecution"]),

 B(slug="gaius", name="Gaius, the wellbeloved", era="Apostolic", charge="Walking in the truth; doing faithfully to the brethren and to strangers; bringing them forward on their journey after a godly sort",
  summary="The third epistle of John is written to him. He kept the travelling brethren, strangers to him, and sent them on their way supplied, and they testified of his charity before the church. In the same short letter Diotrephes is cast out of the church for the opposite. John has no greater joy than to hear that his children walk in truth.",
  offense="Beloved, thou doest faithfully whatsoever thou doest to the brethren, and to strangers; which have borne witness of thy charity before the church: whom if thou bring forward on their journey after a godly sort, thou shalt do well: because that for his name's sake they went forth, taking nothing of the Gentiles. We therefore ought to receive such, that we might be fellowhelpers to the truth.",
  judgment="Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth. For I rejoiced greatly, when the brethren came and testified of the truth that is in thee, even as thou walkest in the truth. I have no greater joy than to hear that my children walk in truth. Beloved, follow not that which is evil, but that which is good. He that doeth good is of God.",
  refs=[R("3 John",1,"1-4"),R("3 John",1,"5-8"),R("3 John",1,"11-12"),R("Romans",12,"13"),R("Hebrews",13,"1-2"),R("Matthew",10,"40-42")],
  laws=["15A","3A","3G","20A"], topics=["strangers","fellowship","brotherly-love","truth"], themes=["hospitality","faith","provision"]),

 B(slug="antipas-smyrna-and-philadelphia", name="Antipas, Smyrna, and Philadelphia", era="Apostolic", charge="Faithful unto death; keeping the word of his patience; not denying his name in the place where Satan's seat is",
  summary="Of the seven churches, two are given no rebuke at all, and one man in a third is named by the Lord himself. Smyrna, poor and slandered, is promised a crown of life. Philadelphia, with a little strength, has an open door no man can shut and will be kept from the hour of temptation. Antipas of Pergamos is called my faithful martyr, slain among them where Satan dwelleth.",
  offense="I know thy works, and tribulation, and poverty, (but thou art rich). Fear none of those things which thou shalt suffer: behold, the devil shall cast some of you into prison, that ye may be tried. Be thou faithful unto death. Thou holdest fast my name, and hast not denied my faith, even in those days wherein Antipas was my faithful martyr, who was slain among you, where Satan dwelleth. Thou hast a little strength, and hast kept my word, and hast not denied my name. Because thou hast kept the word of my patience.",
  judgment="Be thou faithful unto death, and I will give thee a crown of life. He that overcometh shall not be hurt of the second death. Behold, I have set before thee an open door, and no man can shut it. I will make them of the synagogue of Satan to come and worship before thy feet, and to know that I have loved thee. I also will keep thee from the hour of temptation, which shall come upon all the world. Him that overcometh will I make a pillar in the temple of my God, and he shall go no more out: and I will write upon him the name of my God. Behold, I come quickly: hold that fast which thou hast, that no man take thy crown.",
  refs=[R("Revelation",2,"8-11"),R("Revelation",2,"12-13"),R("Revelation",3,"7-13"),R("Revelation",2,"10"),R("James",1,"12"),R("Matthew",10,"22")],
  laws=["2B","2E","2F","2C"], topics=["persecution","keep-faith-and-laws","suffering","overcome","the-name"], themes=["martyrdom","faith","persecution","covenant","patience"]),

 B(slug="paul-at-the-end", name="Paul, at the end of his course", era="Apostolic", charge="I have fought a good fight, I have finished my course, I have kept the faith",
  summary="The man who had held the coats at Stephen's stoning wrote his last letter from a Roman prison, alone except for Luke, with the time of his departure at hand. He gave his own account of himself in one sentence and claimed the crown by name. Before that, five times forty stripes save one, three times beaten with rods, once stoned, three shipwrecks, a night and a day in the deep; and the churches of the Gentiles.",
  offense="For I am now ready to be offered, and the time of my departure is at hand. I have fought a good fight, I have finished my course, I have kept the faith. At my first answer no man stood with me, but all men forsook me: I pray God that it may not be laid to their charge. Notwithstanding the Lord stood with me, and strengthened me; that by me the preaching might be fully known, and that all the Gentiles might hear. I have coveted no man's silver, or gold, or apparel; these hands have ministered unto my necessities.",
  judgment="Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing. And the Lord shall deliver me from every evil work, and will preserve me unto his heavenly kingdom: to whom be glory for ever and ever. The blessing on Saul of Tarsus, whose own case is his persecution of the church, is written by his own hand at the end of it.",
  refs=[R("2 Timothy",4,"6-8"),R("2 Timothy",4,"16-18"),R("Acts",20,"22-24"),R("Acts",20,"33-35"),R("2 Corinthians",11,"23-28"),R("Philippians",3,"13-14"),R("1 Corinthians",9,"24-27")],
  laws=["2B","13D","20A","17E"], topics=["keep-faith-and-laws","suffering","persecution","patience"], themes=["faith","patience","persecution","leadership"]),
]
